    g.add(ped, fig);
  }
  g.userData.collider = { x: 0, z: 0, r: 7.6 };
  g.userData.animate = (t) => { orb.rotation.y = t * 0.7; orb.position.y = 6.3 + Math.sin(t * 1.7) * 0.15; };
  return g;
}

export function createRuins(seed = 1) {
  const g = new THREE.Group();
  const rng = mulberry(seed);
  const stone = '#6a6a60';
  for (let i = 0; i < 6; i++) {
    const ang = rng() * Math.PI * 2;
    const r = 3 + rng() * 8;
    const h = 2 + rng() * 7;
    const col = cyl(0.7, 0.85, h, stone, { x: Math.cos(ang) * r, y: h / 2, z: Math.sin(ang) * r, seg: 6 });
    col.rotation.z = (rng() - 0.5) * 0.4; col.rotation.x = (rng() - 0.5) * 0.3;
    g.add(col);
  }
  g.add(box(7, 0.8, 3, stone, { y: 0.4, rotationY: rng() * 3 }));
  const glow = new THREE.Mesh(new THREE.OctahedronGeometry(0.5, 0), new THREE.MeshStandardMaterial({ color: '#c58cff', emissive: '#9b7fc0', emissiveIntensity: 1.5 }));
  glow.position.y = 2.2; g.add(glow);
  g.userData.animate = (t) => { glow.rotation.y = t; glow.position.y = 2.2 + Math.sin(t * 2) * 0.15; };
  return g;
}

export function createCampfire() {
  const g = new THREE.Group();
  for (let i = 0; i < 5; i++) {
    const log = cyl(0.12, 0.16, 1.6, '#4a3626', { y: 0.25, seg: 5 });
    log.rotation.z = Math.PI / 2; log.rotation.y = i / 5 * Math.PI;
    g.add(log);
  }
  const flame = cone(0.45, 1.2, '#ff8a3a', { y: 1.0, emissive: '#ff6a2a', emissiveIntensity: 2.2, shadow: false, seg: 5 });
  g.add(flame);
  const flame2 = cone(0.25, 0.8, '#ffd479', { y: 0.9, emissive: '#ffcf6a', emissiveIntensity: 2.4, shadow: false, seg: 4 });
  g.add(flame2);
  g.userData.animate = (t) => { flame.scale.y = 1 + Math.sin(t * 8) * 0.15; flame2.scale.y = 1 + Math.sin(t * 11) * 0.2; };
  return g;
}

/* ============================================================
   UTIL
   ============================================================ */
export function mulberry(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}

import * as THREE from 'three';
import { WORLD_SIZE, WORLD_HALF, ZONES, MONSTERS } from './data.js';
import {
  mat, box, sphere, cyl, cone, mulberry,
  createBuilding, createShrine, createWaypoint, createQuestBoard, createFountain, createRuins, createCampfire,
} from './models.js';

/* ---------------- noise ---------------- */
function hash2(x, y) {
  const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123;
  return s - Math.floor(s);
}
function vnoise(x, y) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
  const a = hash2(xi, yi), b = hash2(xi + 1, yi), c = hash2(xi, yi + 1), d = hash2(xi + 1, yi + 1);
  return a * (1 - u) * (1 - v) + b * u * (1 - v) + c * (1 - u) * v + d * u * v;
}
function fbm(x, y, oct = 4) {
  let amt = 0.5, f = 1, sum = 0, norm = 0;
  for (let i = 0; i < oct; i++) {
    sum += vnoise(x * f, y * f) * amt;
    norm += amt; amt *= 0.5; f *= 2.03;
  }
  return sum / norm;
}
const smooth = (a, b, t) => { const x = Math.min(1, Math.max(0, (t - a) / (b - a))); return x * x * (3 - 2 * x); };
const lerp = (a, b, t) => a + (b - a) * t;

export function createWorld(scene) {
  const colliders = [];
  const poi = [];
  const waypoints = [];
  const npcSpawns = [];
  const monsterSpawns = [];
  const animated = [];
  const rng = mulberry(20261120);

  const HUB = { x: 0, z: 0, r: 260 };
  const BOSS = { x: 1920, z: 1880 };

  /* plain settlements list */
  const settlements = [
    { zone: 'verdant', x: -1250, z: -1150, accent: '#8fe08a' },
    { zone: 'ember', x: 1400, z: -1150, accent: '#ff9a5a' },
    { zone: 'frost', x: -1400, z: 1200, accent: '#a8e8ff' },
    { zone: 'umbra', x: 1400, z: 1200, accent: '#c58cff' },
  ];

  /* biomes weights */
  function weights(x, z) {
    const bx = smooth(-420, 420, x);
    const bz = smooth(-420, 420, z);
    return {
      verdant: (1 - bx) * (1 - bz),
      ember: bx * (1 - bz),
      frost: (1 - bx) * bz,
      umbra: bx * bz,
    };
  }
  function rawHeight(x, z) {
    const n = fbm(x * 0.0013 + 11.3, z * 0.0013 - 4.7, 4);
    const n2 = fbm(x * 0.0043 - 3.1, z * 0.0043 + 8.2, 3);
    const ridge = 1 - Math.abs(fbm(x * 0.0028 + 3, z * 0.0028 + 9, 3) * 2 - 1);
    const w = weights(x, z);
    let h =
      w.verdant * (3 + n * 15 + n2 * 2.6) +
      w.ember * (2 + n * 20 + ridge * 16 + n2 * 3.2) +
      w.frost * (8 + n * 13 + n2 * 2.2) +
      w.umbra * (-2 + n * 7.5 + n2 * 1.6);
    const d = Math.hypot(x, z);
    h = lerp(2.1, h, smooth(155, 390, d));
    return h;
  }

  const flattenSpots = [{ x: 0, z: 0, r0: 165, r1: 330, y: 2.1 }];
  for (const s of settlements) flattenSpots.push({ x: s.x, z: s.z, r0: 95, r1: 210, y: rawHeight(s.x, s.z) });
  flattenSpots.push({ x: BOSS.x, z: BOSS.z, r0: 78, r1: 180, y: rawHeight(BOSS.x, BOSS.z) });
  // ruins flatten
  const ruinSpots = [];
  const ruinZones = ['verdant', 'verdant', 'ember', 'frost', 'umbra', 'ember', 'frost', 'umbra'];
  ruinZones.forEach((zone, i) => {
    const cz = ZONES[zone].center;
    let x, z, tries = 0;
    do {
      const a = rng() * Math.PI * 2;
      const r = 280 + rng() * 620;
      x = cz[0] + Math.cos(a) * r;
      z = cz[1] + Math.sin(a) * r;
      tries++;
    } while (tries < 20 && (Math.hypot(x, z) < 430 || settlements.some(s => Math.hypot(s.x - x, s.z - z) < 240) || Math.hypot(x - BOSS.x, z - BOSS.z) < 260));
    flattenSpots.push({ x, z, r0: 18, r1: 48, y: rawHeight(x, z) });
    ruinSpots.push({ zone, x, z });
  });

  function heightAt(x, z) {
    let h = rawHeight(x, z);
    for (const s of flattenSpots) {
      const d = Math.hypot(x - s.x, z - s.z);
      if (d < s.r1) {
        const t = smooth(s.r0, s.r1, d);
        h = lerp(s.y, h, t);
      }
    }
    return h;
  }

  /* ============================================================
     SKY + LIGHTS
     ============================================================ */
  const skyUniforms = {
    topColor: { value: new THREE.Color('#2a3d68') },
    midColor: { value: new THREE.Color('#8fa8c8') },
    horizonColor: { value: new THREE.Color('#f0b888') },
    sunDir: { value: new THREE.Vector3(-0.55, 0.30, -0.78).normalize() },
  };
  const sky = new THREE.Mesh(
    new THREE.SphereGeometry(4200, 32, 20),
    new THREE.ShaderMaterial({
      uniforms: skyUniforms,
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      vertexShader: `varying vec3 vWorld; void main(){ vWorld = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `
        uniform vec3 topColor, midColor, horizonColor, sunDir;
        varying vec3 vWorld;
        void main(){
          vec3 d = normalize(vWorld);
          float h = clamp(d.y, -0.15, 1.0);
          vec3 col = mix(horizonColor, midColor, smoothstep(0.0, 0.28, h));
          col = mix(col, topColor, smoothstep(0.16, 0.85, h));
          float sun = pow(max(dot(d, sunDir), 0.0), 620.0);
          float glow = pow(max(dot(d, sunDir), 0.0), 9.0);
          col += vec3(1.0, 0.72, 0.42) * sun * 2.2;
          col += vec3(1.0, 0.52, 0.24) * glow * 0.24;
          float ground = smoothstep(0.0, -0.12, d.y);
          col = mix(col, vec3(0.18,0.20,0.24), ground);
          gl_FragColor = vec4(col, 1.0);
        }`,
    }),
  );
  sky.renderOrder = -10;
  scene.add(sky);

  // distant sun disc sprite
  const sunPos = new THREE.Vector3(-0.55, 0.30, -0.78).normalize().multiplyScalar(3600);
  const sunSprite = new THREE.Mesh(new THREE.CircleGeometry(140, 32), new THREE.MeshBasicMaterial({ color: '#ffe0b0', transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false, fog: false }));
  sunSprite.position.copy(sunPos);
  sunSprite.lookAt(0, 0, 0);
  sky.add(sunSprite);

  // stars
  const starGeo = new THREE.BufferGeometry();
  const starPos = [];
  for (let i = 0; i < 500; i++) {
    const a = rng() * Math.PI * 2, e = 0.18 + rng() * 1.3, r = 3900;
    starPos.push(Math.cos(a) * Math.cos(e) * r, Math.sin(e) * r, Math.sin(a) * Math.cos(e) * r);
  }
  starGeo.setAttribute('position', new THREE.Float32BufferAttribute(starPos, 3));
  const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({ color: '#dfe8ff', size: 5, sizeAttenuation: false, transparent: true, opacity: 0.55, depthWrite: false, fog: false }));
  sky.add(stars);

  const hemi = new THREE.HemisphereLight('#c8dcf0', '#3a3228', 1.05);
  scene.add(hemi);
  const sun = new THREE.DirectionalLight('#ffd9ac', 2.5);
  sun.position.set(-220, 300, -320);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.left = -90; sun.shadow.camera.right = 90;
  sun.shadow.camera.top = 90; sun.shadow.camera.bottom = -90;
  sun.shadow.camera.near = 1; sun.shadow.camera.far = 900;
  sun.shadow.bias = -0.0008;
  sun.shadow.normalBias = 0.04;
  scene.add(sun);
  scene.add(sun.target);
  const fill = new THREE.DirectionalLight('#6f8fc8', 0.55);
  fill.position.set(200, 140, 260);
  scene.add(fill);
  const ambient = new THREE.AmbientLight('#4a5a72', 0.35);
  scene.add(ambient);

  scene.fog = new THREE.FogExp2('#9aa9bc', 0.00052);

  /* ============================================================
     TERRAIN
     ============================================================ */
  const SEG = 210;
  const geo = new THREE.PlaneGeometry(WORLD_SIZE, WORLD_SIZE, SEG, SEG);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.attributes.position;
  const colors = new Float32Array(pos.count * 3);
  const zoneColors = {};
  for (const [id, z] of Object.entries(ZONES)) {
    zoneColors[id] = {
      soil: new THREE.Color(z.soil), accent: new THREE.Color(z.accent), color: new THREE.Color(z.color),
    };
  }
  const cTmp = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), z = pos.getZ(i);
    const y = heightAt(x, z);
    pos.setY(i, y);
    const w = weights(x, z);
    const n = fbm(x * 0.01, z * 0.01, 2);
    const n2 = fbm(x * 0.035 + 41, z * 0.035 - 9, 2);
    cTmp.setRGB(0, 0, 0);
    for (const id of ['verdant', 'ember', 'frost', 'umbra']) {
      const ww = w[id];
      if (ww <= 0.001) continue;
      const base = zoneColors[id].soil.clone();
      const alt = zoneColors[id].accent.clone();
      base.lerp(alt, n * 0.55 + n2 * 0.16);
      base.multiplyScalar(0.82 + n2 * 0.3);
      cTmp.r += base.r * ww; cTmp.g += base.g * ww; cTmp.b += base.b * ww;
    }
    // darken low umbra / brighten frost peaks
    if (w.umbra > 0.3 && y < 2) cTmp.multiplyScalar(0.72);
    if (w.frost > 0.4) cTmp.lerp(new THREE.Color('#eef6fa'), 0.25 + n2 * 0.2);
    if (w.ember > 0.4) {
      const lava = smooth(0.55, 0.78, fbm(x * 0.006 + 8, z * 0.006 - 2, 3));
      cTmp.lerp(new THREE.Color('#ff6a2a'), lava * 0.22);
    }
    if (y > 22) cTmp.lerp(new THREE.Color('#7f8a90'), smooth(22, 38, y) * 0.4);
    colors[i * 3] = cTmp.r; colors[i * 3 + 1] = cTmp.g; colors[i * 3 + 2] = cTmp.b;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  geo.computeVertexNormals();
  const terrain = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.96, metalness: 0.02, flatShading: true }));
  terrain.receiveShadow = true;
  scene.add(terrain);

  /* water pools */
  const pools = new THREE.Group();
  scene.add(pools);
  const poolMats = {
    umbra: new THREE.MeshStandardMaterial({ color: '#2e4a44', emissive: '#1e3a34', emissiveIntensity: 0.3, transparent: true, opacity: 0.88, roughness: 0.16, metalness: 0.35 }),
    frost: new THREE.MeshStandardMaterial({ color: '#9fd0e0', emissive: '#6aa8c0', emissiveIntensity: 0.22, transparent: true, opacity: 0.8, roughness: 0.1, metalness: 0.4 }),
    ember: new THREE.MeshStandardMaterial({ color: '#ff6a2a', emissive: '#ff5a1a', emissiveIntensity: 1.4, transparent: true, opacity: 0.92, roughness: 0.3 }),
  };
  for (let i = 0; i < 26; i++) {
    const zone = i % 3 === 0 ? 'umbra' : i % 3 === 1 ? 'frost' : 'ember';
    const cz = ZONES[zone].center;
    const x = cz[0] + (rng() - 0.5) * 1200;
    const z = cz[1] + (rng() - 0.5) * 1200;
    if (Math.hypot(x, z) < 500 || settlements.some(s => Math.hypot(s.x - x, s.z - z) < 190)) continue;
    if (Math.hypot(x - BOSS.x, z - BOSS.z) < 260) continue;
    const r = 9 + rng() * 20;
    const y = heightAt(x, z) + 0.28;
    const p = new THREE.Mesh(new THREE.CircleGeometry(r, 18), poolMats[zone]);
    p.rotation.x = -Math.PI / 2;
    p.position.set(x, y, z);
    p.renderOrder = 1;
    pools.add(p);
    if (zone === 'umbra' || zone === 'frost') {
      for (let k = 0; k < 5; k++) {
        const ra = rng() * Math.PI * 2, rr = r * (0.5 + rng() * 0.6);
        const reed = cyl(0.05, 0.07, 1.2 + rng() * 0.8, '#4a5a3a', { x: x + Math.cos(ra) * rr, y: y + 0.6, z: z + Math.sin(ra) * rr, seg: 4 });
        reed.rotation.z = (rng() - 0.5) * 0.3;
        pools.add(reed);
      }
    }
  }

  /* roads */
  const roadMat = new THREE.MeshStandardMaterial({ color: '#93815f', roughness: 1, flatShading: true, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 });
  function road(points, width = 7) {
    const pts = [];
    for (let i = 0; i < points.length - 1; i++) {
      const a = points[i], b = points[i + 1];
      const segs = Math.max(8, Math.floor(Math.hypot(b[0] - a[0], b[1] - a[1]) / 24));
      for (let s = 0; s < segs; s++) {
        const t = s / segs;
        const x = lerp(a[0], b[0], t), z = lerp(a[1], b[1], t);
        pts.push(new THREE.Vector3(x, heightAt(x, z) + 0.12, z));
      }
    }
    pts.push(new THREE.Vector3(points.at(-1)[0], heightAt(points.at(-1)[0], points.at(-1)[1]) + 0.12, points.at(-1)[1]));
    const verts = [], idx = [];
    for (let i = 0; i < pts.length; i++) {
      const p = pts[i];
      const next = pts[Math.min(pts.length - 1, i + 1)];
      const prev = pts[Math.max(0, i - 1)];
      const dir = new THREE.Vector3().subVectors(next, prev).setY(0).normalize();
      const side = new THREE.Vector3(-dir.z, 0, dir.x).multiplyScalar(width / 2);
      verts.push(p.x + side.x, p.y, p.z + side.z, p.x - side.x, p.y, p.z - side.z);
      if (i < pts.length - 1) {
        const k = i * 2;
        idx.push(k, k + 2, k + 1, k + 1, k + 2, k + 3);
      }
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
    g.setIndex(idx);
    g.computeVertexNormals();
    const m = new THREE.Mesh(g, roadMat);
    m.receiveShadow = true;
    scene.add(m);
  }
  for (const s of settlements) {
    const midx = s.x * 0.52, midz = s.z * 0.5;
    road([[s.x * 0.09, s.z * 0.09], [midx + s.z * 0.05, midz - s.x * 0.05], [s.x * 0.86, s.z * 0.86], [s.x, s.z]], 8);
  }
  road([[-1800, 300], [-900, 260], [-260, 60]], 5.5);
  road([[700, -700], [1200, -260], [1200, 60]], 5.5);
  road([[BOSS.x - 170, BOSS.z - 40], [BOSS.x - 380, BOSS.z - 120], [BOSS.x - 640, BOSS.z - 240]], 6);

  /* ============================================================
     PROPS (instanced)
     ============================================================ */
  const dummy = new THREE.Object3D();
  const instanced = [];
  function makeInstanced(geometry, material, instances, name) {
    if (!instances.length) return null;
    const m = new THREE.InstancedMesh(geometry, material, instances.length);
    m.castShadow = true; m.receiveShadow = true;
    instances.forEach((inst, i) => {
      dummy.position.set(inst.x, inst.y, inst.z);
      dummy.rotation.set(inst.rx || 0, inst.ry || 0, inst.rz || 0);
      dummy.scale.setScalar(inst.s || 1);
      dummy.updateMatrix();
      m.setMatrixAt(i, dummy.matrix);
      if (inst.color) m.setColorAt(i, inst.color);
    });
    m.instanceMatrix.needsUpdate = true;
    if (m.instanceColor) m.instanceColor.needsUpdate = true;
    m.frustumCulled = false;
    m.name = name;
    scene.add(m);
    instanced.push(m);
    return m;
  }

  function isFree(x, z, pad = 0) {
    if (Math.hypot(x, z) < 180 + pad) return false;
    for (const s of settlements) if (Math.hypot(x - s.x, z - s.z) < 155 + pad) return false;
    if (Math.hypot(x - BOSS.x, z - BOSS.z) < 160 + pad) return false;
    for (const r of ruinSpots) if (Math.hypot(x - r.x, z - r.z) < 52 + pad) return false;
    return true;
  }
  function zoneAt(x, z) {
    const w = weights(x, z);
    return Object.entries(w).sort((a, b) => b[1] - a[1])[0][0];
  }

  const broad = [], pine = [], dead = [], mushroom = [], rocks = [], crystals = [], grass = [], reeds = [], lavaRock = [], iceShard = [];
  const zoneFoliage = {
    verdant: { leaf: ['#4f8a3c', '#66a34a', '#7cb858', '#3f7634'], trunk: '#5a4430', ground: '#79a858' },
    ember: { leaf: ['#6a3a2e', '#8a4534', '#5a2e26'], trunk: '#4a3428', ground: '#8a5a42' },
    frost: { leaf: ['#b8d8e0', '#cfe6ee', '#a0c4d0'], trunk: '#5a5048', ground: '#a8c0c8' },
    umbra: { leaf: ['#4a5a48', '#5f6a4f', '#3a4538'], trunk: '#3a3230', ground: '#5a6a4a' },
  };
  for (let i = 0; i < 26000 && (broad.length + pine.length + dead.length + mushroom.length) < 2600; i++) {
    const x = (rng() - 0.5) * (WORLD_SIZE - 120);
    const z = (rng() - 0.5) * (WORLD_SIZE - 120);
    if (!isFree(x, z)) continue;
    const zone = zoneAt(x, z);
    const y = heightAt(x, z);
    const dens = fbm(x * 0.008 + 70, z * 0.008 - 30, 2);
    if (dens < 0.32) continue;
    const col = zoneFoliage[zone];
    const leaf = new THREE.Color(col.leaf[Math.floor(rng() * col.leaf.length)]);
    const s = 0.75 + rng() * 0.7;
    if (zone === 'verdant') {
      if (rng() < 0.62) broad.push({ x, y, z, s, ry: rng() * 6.28, color: leaf });
      else pine.push({ x, y, z, s: s * 0.9, ry: rng() * 6.28, color: leaf });
    } else if (zone === 'ember') {
      if (rng() < 0.55) dead.push({ x, y, z, s, ry: rng() * 6.28, rx: (rng() - 0.5) * 0.15, color: new THREE.Color('#4a3428') });
      else broad.push({ x, y, z, s: s * 0.8, ry: rng() * 6.28, color: new THREE.Color('#5a3a2a') });
    } else if (zone === 'frost') {
      pine.push({ x, y, z, s: s * (0.85 + rng() * 0.4), ry: rng() * 6.28, color: leaf });
    } else {
      if (rng() < 0.5) mushroom.push({ x, y, z, s: 0.8 + rng() * 1.3, ry: rng() * 6.28, color: new THREE.Color(rng() < 0.5 ? '#7a5a8a' : '#4a6a5a') });
      else dead.push({ x, y, z, s, ry: rng() * 6.28, rx: (rng() - 0.5) * 0.25, color: new THREE.Color('#3a3438') });
    }
  }
  // rocks
  for (let i = 0; i < 11000 && rocks.length < 1100; i++) {
    const x = (rng() - 0.5) * (WORLD_SIZE - 80);
    const z = (rng() - 0.5) * (WORLD_SIZE - 80);
    if (!isFree(x, z, -10)) continue;
    const zone = zoneAt(x, z);
    const y = heightAt(x, z);
    const c = zone === 'ember' ? '#5a4038' : zone === 'frost' ? '#8a9aa2' : zone === 'umbra' ? '#4a4a44' : '#7a7a6a';
    rocks.push({ x, y: y - 0.2, z, s: 0.5 + rng() * 1.8, ry: rng() * 6.28, rx: rng() * 0.3, color: new THREE.Color(c) });
  }
  // crystals / shards
  for (let i = 0; i < 9000 && (crystals.length + lavaRock.length + iceShard.length) < 620; i++) {
    const x = (rng() - 0.5) * (WORLD_SIZE - 200);
    const z = (rng() - 0.5) * (WORLD_SIZE - 200);
    if (!isFree(x, z)) continue;
    const zone = zoneAt(x, z);
    if (zone === 'verdant') continue;
    const y = heightAt(x, z);
    if (zone === 'ember') lavaRock.push({ x, y, z, s: 0.4 + rng() * 1.1, ry: rng() * 6.28, color: new THREE.Color('#ff7a3a') });
    else if (zone === 'frost') iceShard.push({ x, y, z, s: 0.35 + rng() * 0.9, ry: rng() * 6.28, rz: (rng() - 0.5) * 0.3, color: new THREE.Color('#b8ecff') });
    else crystals.push({ x, y, z, s: 0.5 + rng() * 1.2, ry: rng() * 6.28, color: new THREE.Color('#c58cff') });
  }
  // grass / ground cover
  for (let i = 0; i < 22000 && grass.length < 5200; i++) {
    const x = (rng() - 0.5) * (WORLD_SIZE - 100);
    const z = (rng() - 0.5) * (WORLD_SIZE - 100);
    if (!isFree(x, z, -30)) continue;
    const zone = zoneAt(x, z);
    if (zone === 'ember') continue;
    grass.push({ x, y: heightAt(x, z), z, s: 0.5 + rng() * 1.2, ry: rng() * 6.28, color: new THREE.Color(zoneFoliage[zone].ground) });
  }

  const trunkGeo = new THREE.CylinderGeometry(0.32, 0.55, 4.2, 5);
  trunkGeo.translate(0, 2.1, 0);
  const broadGeo = new THREE.IcosahedronGeometry(2.5, 1);
  broadGeo.translate(0, 5.4, 0);
  const pineGeo = new THREE.ConeGeometry(2.4, 7.2, 6);
  pineGeo.translate(0, 5.0, 0);
  const deadGeo = new THREE.CylinderGeometry(0.22, 0.55, 5.4, 5);
  deadGeo.translate(0, 2.7, 0);
  const mushGeo = new THREE.CylinderGeometry(0.22, 0.3, 1.6, 5);
  mushGeo.translate(0, 0.8, 0);

  const flatMat = (color = '#ffffff') => new THREE.MeshStandardMaterial({ color, roughness: 0.9, flatShading: true });
  makeInstanced(trunkGeo, flatMat(), [...broad.map(b => ({ ...b, color: new THREE.Color('#5a4430') })), ...pine.map(p => ({ ...p, color: new THREE.Color(zoneAt(p.x, p.z) === 'frost' ? '#4a4238' : '#4a3828') }))], 'trunks');
  makeInstanced(broadGeo, flatMat(), broad, 'broadleaf');
  makeInstanced(pineGeo, flatMat('#ffffff'), pine.map(p => ({ ...p, color: new THREE.Color(zoneAt(p.x, p.z) === 'frost' ? '#cfdfe6' : p.color) })), 'pines');
  makeInstanced(deadGeo, flatMat('#ffffff'), dead, 'deadwood');
  // mushroom caps
  const capGeo = new THREE.SphereGeometry(0.85, 7, 4, 0, Math.PI * 2, 0, Math.PI / 2);
  capGeo.translate(0, 1.6, 0);
  makeInstanced(mushGeo, flatMat('#d8d0b8'), mushroom.map(m => ({ ...m, color: new THREE.Color('#c8c0a8') })), 'mushstem');
  makeInstanced(capGeo, new THREE.MeshStandardMaterial({ color: '#ffffff', roughness: 0.7, emissive: '#3a2a4a', emissiveIntensity: 0.35, flatShading: true, side: THREE.DoubleSide }), mushroom, 'mushrooms');
  makeInstanced(new THREE.IcosahedronGeometry(1.1, 0), flatMat('#ffffff'), rocks, 'rocks');
  makeInstanced(new THREE.OctahedronGeometry(0.75, 0), new THREE.MeshStandardMaterial({ color: '#ffffff', emissive: '#b48bd8', emissiveIntensity: 1.2, roughness: 0.2, flatShading: true }), crystals, 'crystals');
  makeInstanced(new THREE.OctahedronGeometry(0.8, 0), new THREE.MeshStandardMaterial({ color: '#ffffff', emissive: '#9fe8ff', emissiveIntensity: 0.9, roughness: 0.1, transparent: true, opacity: 0.85, flatShading: true }), iceShard, 'ice');
  makeInstanced(new THREE.DodecahedronGeometry(0.7, 0), new THREE.MeshStandardMaterial({ color: '#ffffff', emissive: '#ff5a1a', emissiveIntensity: 1.5, roughness: 0.6, flatShading: true }), lavaRock, 'lavarock');
  const grassGeo = new THREE.ConeGeometry(0.18, 0.9, 3);
  grassGeo.translate(0, 0.45, 0);
  const grassMesh = makeInstanced(grassGeo, new THREE.MeshStandardMaterial({ color: '#ffffff', roughness: 1, flatShading: true }), grass, 'grass');
  if (grassMesh) grassMesh.castShadow = false;

  /* floating particles */
  const particleGeo = new THREE.BufferGeometry();
  const N = 900;
  const pPos = new Float32Array(N * 3);
  const pSeed = new Float32Array(N);
  for (let i = 0; i < N; i++) {
    pPos[i * 3] = (rng() - 0.5) * 320;
    pPos[i * 3 + 1] = rng() * 26 + 2;
    pPos[i * 3 + 2] = (rng() - 0.5) * 320;
    pSeed[i] = rng();
  }
  particleGeo.setAttribute('position', new THREE.BufferAttribute(pPos, 3));
  particleGeo.setAttribute('aSeed', new THREE.BufferAttribute(pSeed, 1));
  const particleMat = new THREE.PointsMaterial({ color: '#ffe0a8', size: 0.5, transparent: true, opacity: 0.65, blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true });
  const particles = new THREE.Points(particleGeo, particleMat);
  particles.frustumCulled = false;
  scene.add(particles);

  /* clouds */
  const clouds = new THREE.Group();
  const cloudMat = new THREE.MeshBasicMaterial({ color: '#dfe4ee', transparent: true, opacity: 0.19, depthWrite: false, fog: false });
  for (let i = 0; i < 26; i++) {
    const c = new THREE.Group();
    const n = 3 + Math.floor(rng() * 4);
    for (let k = 0; k < n; k++) {
      const s = new THREE.Mesh(new THREE.SphereGeometry(12 + rng() * 22, 7, 5), cloudMat);
      s.position.set((rng() - 0.5) * 60, (rng() - 0.5) * 10, (rng() - 0.5) * 40);
      s.scale.y = 0.35;
      c.add(s);
    }
    c.position.set((rng() - 0.5) * 3600, 190 + rng() * 90, (rng() - 0.5) * 3600);
    c.userData.speed = 1.5 + rng() * 3;
    clouds.add(c);
  }
  scene.add(clouds);

  /* ============================================================
     HUB TOWN
     ============================================================ */
  const hubGroup = new THREE.Group();
  scene.add(hubGroup);
  const plazaY = heightAt(0, 0);
  const plaza = new THREE.Mesh(new THREE.CircleGeometry(54, 48), new THREE.MeshStandardMaterial({ color: '#a39a86', roughness: 0.9, flatShading: true, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 }));
  plaza.rotation.x = -Math.PI / 2;
  plaza.position.set(0, plazaY + 0.18, 0);
  plaza.receiveShadow = true;
  hubGroup.add(plaza);
  for (let i = 1; i <= 3; i++) {
    const ring = new THREE.Mesh(new THREE.TorusGeometry(14 * i, 0.22, 4, 64), new THREE.MeshStandardMaterial({ color: i === 2 ? '#b8a888' : '#8a8474', roughness: 0.9 }));
    ring.rotation.x = -Math.PI / 2; ring.position.set(0, plazaY + 0.25, 0);
    hubGroup.add(ring);
  }
  const fountain = createFountain();
  fountain.position.set(0, plazaY, 0);
  hubGroup.add(fountain);
  colliders.push({ x: 0, z: 0, r: 8.2, y: plazaY + 6 });
  animated.push(fountain);

  function placeBuilding(type, x, z, rotFace = true, scale = 1, seed = 1, accent) {
    const y = heightAt(x, z);
    const b = createBuilding(type, { x, z, y: y - 0.25, rot: rotFace ? Math.atan2(-x, -z) : 0, scale, seed, accent });
    scene.add(b);
    const col = b.userData.collider;
    colliders.push(col);
    return b;
  }

  const hubBuildings = [
    ['tavern', -56, -34, 1.05, '#8a3a3a'],
    ['smithy', 58, -30, 0.95, '#c25a35'],
    ['shop', 58, 40, 0.9, '#3f7a6a'],
    ['temple', -58, 42, 1.0, '#4a6a8a'],
    ['house', -24, -74, 0.85, '#7a5a3a'],
    ['house', 20, 76, 0.9, '#6a5a4a'],
    ['tower', 96, 6, 1.0, '#8a6a4a'],
    ['tent', -12, 64, 1.15, '#5a3a6a'],
  ];
  hubBuildings.forEach(([type, x, z, s, accent], i) => placeBuilding(type, x, z, true, s, 11 + i, accent));

  // gacha tent lanterns
  const gachaTent = { x: -12, z: 64 };
  for (let i = 0; i < 4; i++) {
    const a = i / 4 * Math.PI * 2;
    const lamp = sphere(0.32, '#ffcf6a', { x: gachaTent.x + Math.cos(a) * 7, y: heightAt(gachaTent.x, gachaTent.z) + 3.2, z: gachaTent.z + Math.sin(a) * 7, emissive: '#ffcf6a', emissiveIntensity: 2.4, shadow: false });
    hubGroup.add(lamp);
  }

  // market stalls around plaza
  function stall(x, z, rot, accent) {
    const y = heightAt(x, z);
    const g = new THREE.Group();
    g.position.set(x, y, z); g.rotation.y = rot;
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) g.add(box(0.15, 2.4, 0.15, '#5a4230', { x: sx * 1.8, y: 1.2, z: sz * 1.2 }));
    const canopy = box(4.4, 0.16, 3.2, accent, { y: 2.6 });
    canopy.rotation.z = 0.06; g.add(canopy);
    g.add(box(3.4, 0.7, 1.6, '#6a5030', { y: 0.9, z: 0.5 }));
    g.add(box(0.9, 0.45, 0.8, '#8a6a3a', { x: -1.1, y: 1.5, z: 0.4 }));
    g.add(sphere(0.18, '#ffcf6a', { x: 1.8, y: 2.15, z: 1.3, emissive: '#ffcf6a', emissiveIntensity: 1.8, shadow: false }));
    g.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
    scene.add(g);
    colliders.push({ x, z, r: 2.4 });
  }
  stall(-30, 22, 0.4, '#8a3a3a');
  stall(26, 25, -0.4, '#3a6a6a');

  // plaza lanterns
  for (let i = 0; i < 8; i++) {
    const a = i / 8 * Math.PI * 2 + 0.2;
    const x = Math.cos(a) * 33, z = Math.sin(a) * 33;
    const y = heightAt(x, z);
    const pole = cyl(0.09, 0.13, 4.2, '#3a3430', { x, y: y + 2.1, z, seg: 5 });
    pole.castShadow = true;
    const lamp = sphere(0.34, '#ffe0a0', { x, y: y + 4.3, z, emissive: '#ffcf6a', emissiveIntensity: 2.2, shadow: false });
    hubGroup.add(pole, lamp);
  }

  // waypoints
  function addWaypoint(id, name, zone, x, z, accent) {
    const y = heightAt(x, z);
    const wp = createWaypoint(accent);
    wp.position.set(x, y, z);
    scene.add(wp);
    animated.push(wp);
    colliders.push({ x, z, r: 2.2 });
    waypoints.push({ id, name, zone, x, z, y, accent, unlocked: false });
  }
  addWaypoint('hub', "Wayfarer's Rest", 'hub', 0, -30, '#74e7f7');
  addWaypoint('verdant', 'Verdant Watch', 'verdant', -1250, -1055, '#8fe08a');
  addWaypoint('ember', 'Emberwatch', 'ember', 1400, -1055, '#ff9a5a');
  addWaypoint('frost', 'Frosthearth', 'frost', -1400, 1105, '#a8e8ff');
  addWaypoint('umbra', 'Mirefall', 'umbra', 1400, 1105, '#c58cff');

  poi.push({ id: 'hub', name: "Wayfarer's Rest", type: 'town', zone: 'hub', x: 0, z: 0 });
  for (const s of settlements) {
    poi.push({ id: s.zone, name: ZONES[s.zone].settlement, type: 'town', zone: s.zone, x: s.x, z: s.z });
  }

  /* settlements */
  const settlementNpcs = {
    verdant: { warden: 'saelis', vendor: 'fen', storyteller: 'orla' },
    ember: { warden: 'ignis', vendor: 'kael', storyteller: 'ash' },
    frost: { warden: 'yrsa', vendor: 'niva', storyteller: 'maiden' },
    umbra: { warden: 'morthos', vendor: 'sable', storyteller: 'oracle' },
  };
  for (const s of settlements) {
    const zone = ZONES[s.zone];
    const baseY = heightAt(s.x, s.z);
    const g = new THREE.Group();
    g.position.set(s.x, 0, s.z);
    scene.add(g);

    // circular plaza
    const disc = new THREE.Mesh(new THREE.CircleGeometry(30, 32), new THREE.MeshStandardMaterial({ color: s.zone === 'frost' ? '#b8c8d0' : s.zone === 'ember' ? '#6a4a3a' : s.zone === 'umbra' ? '#5a5a50' : '#8a8a6a', roughness: 0.95, flatShading: true, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 }));
    disc.rotation.x = -Math.PI / 2; disc.position.set(s.x, baseY + 0.16, s.z); disc.receiveShadow = true; scene.add(disc);

    // shrine
    const shrine = createShrine(s.accent, 1);
    shrine.position.set(s.x, baseY, s.z);
    scene.add(shrine);
    animated.push(shrine);
    colliders.push({ x: s.x, z: s.z, r: 5.4 });
    poi.push({ id: `shrine_${s.zone}`, name: `${zone.name} Shrine`, type: 'shrine', zone: s.zone, x: s.x, z: s.z });

    // surrounding buildings
    const types = s.zone === 'ember' ? ['smithy', 'house', 'shop'] : s.zone === 'frost' ? ['temple', 'house', 'shop'] : s.zone === 'umbra' ? ['tavern', 'house', 'tower'] : ['tavern', 'house', 'shop'];
    const offsets = [[-58, -40], [62, -30], [-30, 64]];
    types.forEach((type, i) => {
      const bx = s.x + offsets[i][0], bz = s.z + offsets[i][1];
      const b = createBuilding(type, { x: bx, z: bz, y: heightAt(bx, bz) - 0.2, rot: Math.atan2(s.x - bx, s.z - bz), seed: 40 + i + s.x, accent: s.accent });
      scene.add(b);
      colliders.push(b.userData.collider);
    });

    // vendor stall + crates
    const vx = s.x + 46, vz = s.z + 20;
    const vy = heightAt(vx, vz);
    const vg = new THREE.Group(); vg.position.set(vx, vy, vz); vg.rotation.y = -0.8;
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) vg.add(box(0.15, 2.5, 0.15, '#5a4230', { x: sx * 1.9, y: 1.25, z: sz * 1.25 }));
    const can = box(4.6, 0.16, 3.4, s.accent, { y: 2.7 }); can.rotation.z = 0.05; vg.add(can);
    vg.add(box(3.6, 0.75, 1.7, '#6a5030', { y: 0.9, z: 0.55 }));
    vg.add(box(1.0, 0.5, 0.9, '#8a6a3a', { x: -1.2, y: 1.5, z: 0.5 }));
    vg.add(sphere(0.18, '#ffcf6a', { x: 1.9, y: 2.2, z: 1.4, emissive: '#ffcf6a', emissiveIntensity: 1.8, shadow: false }));
    vg.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
    scene.add(vg);
    colliders.push({ x: vx, z: vz, r: 2.7 });

    // quest board
    const qx = s.x - 34, qz = s.z + 24;
    const board = createQuestBoard();
    board.position.set(qx, heightAt(qx, qz), qz);
    board.rotation.y = Math.atan2(s.x - qx, s.z - qz);
    scene.add(board);
    colliders.push({ x: qx, z: qz, r: 2.2 });

    // campfire
    const fx = s.x + 18, fz = s.z + 44;
    const fire = createCampfire();
    fire.position.set(fx, heightAt(fx, fz), fz);
    scene.add(fire);
    animated.push(fire);
    colliders.push({ x: fx, z: fz, r: 1.6 });

    // npc spawns
    const names = settlementNpcs[s.zone];
    const wardenPos = { x: s.x + 10, z: s.z + 12 };
    const vendorPos = { x: s.x + 48, z: s.z + 26 };
    const storyPos = { x: s.x + 16, z: s.z + 47 };
    npcSpawns.push({ npc: names.warden, x: wardenPos.x, z: wardenPos.z, rot: Math.atan2(s.x - wardenPos.x, s.z - wardenPos.z) });
    npcSpawns.push({ npc: names.vendor, x: vendorPos.x, z: vendorPos.z, rot: -0.8 + Math.PI });
    npcSpawns.push({ npc: names.storyteller, x: storyPos.x, z: storyPos.z, rot: Math.atan2(fx - storyPos.x, fz - storyPos.z) });

    // zone monster spawns
    const monsters = ZONES[s.zone].monsters;
    for (let i = 0; i < 26; i++) {
      const a = rng() * Math.PI * 2;
      const r = 180 + rng() * 700;
      const x = s.x + Math.cos(a) * r;
      const z = s.z + Math.sin(a) * r;
      if (Math.abs(x) > WORLD_HALF - 120 || Math.abs(z) > WORLD_HALF - 120) continue;
      if (Math.hypot(x, z) < 380) continue;
      if (settlements.some(o => Math.hypot(o.x - x, o.z - z) < 150)) continue;
      const pool = i < 10 ? monsters.slice(0, 3) : monsters;
      const type = pool[Math.floor(rng() * pool.length)];
      monsterSpawns.push({ type, x, z });
    }

    // banners along the approach
    for (let i = 0; i < 2; i++) {
      const bx = s.x + (i ? 34 : -38), bz = s.z - 54 - i * 8;
      const by = heightAt(bx, bz);
      hubGroup.add(cyl(0.08, 0.1, 4.6, '#3a3430', { x: bx, y: by + 2.3, z: bz, seg: 5 }));
      const ban = box(0.08, 1.8, 0.9, s.accent, { x: bx + 0.1, y: by + 3.4, z: bz });
      hubGroup.add(ban);
    }
  }

  // hub NPCs
  npcSpawns.push({ npc: 'elder', x: 0, z: 17, rot: Math.PI });
  npcSpawns.push({ npc: 'orin', x: 53, z: -14, rot: 0.6 });
  npcSpawns.push({ npc: 'bram', x: 52, z: 51, rot: -0.7 });
  npcSpawns.push({ npc: 'lyra', x: -12, z: 66, rot: Math.PI });

  // starter slimes around hub (tutorial)
  const starterPos = [[64, 62], [-76, 54], [70, -70], [-52, -78], [94, 16], [-98, -12]];
  for (const [x, z] of starterPos) monsterSpawns.push({ type: 'moss_slime', x, z, starter: true });
  monsterSpawns.push({ type: 'grey_wolf', x: 108, z: 96 });
  monsterSpawns.push({ type: 'grey_wolf', x: -118, z: 86 });

  /* quest board at hub */
  const hubBoard = createQuestBoard();
  hubBoard.position.set(34, heightAt(34, 6), 6);
  hubBoard.rotation.y = -0.8;
  scene.add(hubBoard);
  colliders.push({ x: 34, z: 6, r: 2.2 });
  poi.push({ id: 'board_hub', name: "Wayfarer's Quest Board", type: 'board', zone: 'hub', x: 34, z: 6 });

  /* ============================================================
     RUINS
     ============================================================ */
  ruinSpots.forEach((r, i) => {
    const y = heightAt(r.x, r.z);
    const ruin = createRuins(i + 3);
    ruin.position.set(r.x, y, r.z);
    scene.add(ruin);
    animated.push(ruin);
    const names = ['The Fallen Span', 'Hollow Chapel', 'Cinder Barracks', 'Weeping Stones', 'The Sunken Court', 'Ashen Observatory', 'The Glass Garden', 'Mouth of Names'];
    const p = { id: `ruin_${i}`, name: names[i], type: 'ruin', zone: r.zone, x: r.x, z: r.z };
    poi.push(p);
    // a few monsters guard each ruin
    const zoneMonsters = ZONES[r.zone].monsters;
    for (let k = 0; k < 3; k++) {
      const a = rng() * Math.PI * 2, r2 = 14 + rng() * 26;
      monsterSpawns.push({ type: zoneMonsters[Math.min(zoneMonsters.length - 1, 1 + Math.floor(rng() * 4))], x: r.x + Math.cos(a) * r2, z: r.z + Math.sin(a) * r2 });
    }
  });

  /* ============================================================
     BOSS ARENA
     ============================================================ */
  const bossY = heightAt(BOSS.x, BOSS.z);
  const arena = new THREE.Group();
  arena.position.set(BOSS.x, bossY, BOSS.z);
  scene.add(arena);
  const plat = new THREE.Mesh(new THREE.CylinderGeometry(52, 56, 1.2, 32), new THREE.MeshStandardMaterial({ color: '#2a2430', roughness: 0.85, flatShading: true }));
  plat.position.y = 0.6; plat.receiveShadow = true; arena.add(plat);
  const ring = new THREE.Mesh(new THREE.TorusGeometry(48, 0.5, 4, 48), new THREE.MeshStandardMaterial({ color: '#8a6aa0', emissive: '#6a3a8a', emissiveIntensity: 0.9 }));
  ring.rotation.x = -Math.PI / 2; ring.position.y = 1.25; arena.add(ring);
  for (let i = 0; i < 10; i++) {
    const a = i / 10 * Math.PI * 2;
    const r = 45;
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    const h = 5 + (i % 3) * 4;
    const pillar = box(2.2, h, 2.2, '#3a3040', { x, y: h / 2 + 1, z });
    pillar.rotation.y = a; arena.add(pillar);
    if (i % 2 === 0) {
      const br = createCampfire();
      br.scale.setScalar(3);
      br.position.set(x * 0.86, 1.2, z * 0.86);
      arena.add(br);
      animated.push(br);
    }
  }
  // throne
  const throneX = 0, throneZ = -30;
  arena.add(box(10, 2, 8, '#241e2a', { x: throneX, y: 2, z: throneZ }));
  arena.add(box(8, 10, 2, '#241e2a', { x: throneX, y: 6, z: throneZ - 3 }));
  arena.add(box(2, 6, 6, '#3a3040', { x: throneX - 4, y: 4, z: throneZ }));
  arena.add(box(2, 6, 6, '#3a3040', { x: throneX + 4, y: 4, z: throneZ }));
  for (let i = 0; i < 3; i++) {
    const sp = cone(0.5, 4, '#c58cff', { x: throneX + (i - 1) * 2.2, y: 12, z: throneZ - 3, emissive: '#7c3aed', emissiveIntensity: 1.3 });
    arena.add(sp);
  }
  const bossCrystal = new THREE.Mesh(new THREE.OctahedronGeometry(3, 0), new THREE.MeshStandardMaterial({ color: '#ffcf6a', emissive: '#ff9a3a', emissiveIntensity: 2, transparent: true, opacity: 0.9, flatShading: true }));
  bossCrystal.position.set(0, 17, -30); arena.add(bossCrystal);
  animated.push({ userData: { animate: (t) => { bossCrystal.rotation.y = t * 0.4; bossCrystal.position.y = 17 + Math.sin(t) * 0.5; } } });
  colliders.push({ x: BOSS.x, z: BOSS.z - 30, r: 7 });
  poi.push({ id: 'boss', name: 'The Sundered Throne', type: 'boss', zone: 'umbra', x: BOSS.x, z: BOSS.z });

  // arena waypoint
  addWaypoint('throne', 'Sundered Threshold', 'umbra', BOSS.x - 70, BOSS.z + 20, '#ff9a5a');
  poi.push({ id: 'waypoint_throne', name: 'Sundered Threshold', type: 'waypoint', zone: 'umbra', x: BOSS.x - 70, z: BOSS.z + 20 });

  monsterSpawns.push({ type: 'boss', x: BOSS.x, z: BOSS.z + 8, boss: true });

  /* clouds update + particles */
  let lightTimer = 0;
  function update(dt, time, camera, playerPos) {
    sky.position.copy(camera.position);
    stars.material.opacity = 0.5;
    for (const obj of animated) if (obj.userData.animate) obj.userData.animate(time);
    clouds.children.forEach(c => {
      c.position.x += c.userData.speed * dt;
      if (c.position.x > 2000) c.position.x = -2000;
    });
    particles.rotation.y = time * 0.008;
    particles.position.set(playerPos.x, 0, playerPos.z);
    sun.position.set(playerPos.x - 220, playerPos.y + 300, playerPos.z - 320);
    sun.target.position.set(playerPos.x, playerPos.y, playerPos.z);
    sun.target.updateMatrixWorld();
    // adjust fog to zone
    const w = weights(playerPos.x, playerPos.z);
    const zone = Object.entries(w).sort((a, b) => b[1] - a[1])[0][0];
    const targetFog = new THREE.Color(ZONES[zone].fog);
    scene.fog.color.lerp(targetFog, Math.min(1, dt * 0.7));
    const zc = ZONES[zone];
    particleMat.color.lerp(new THREE.Color(zone === 'ember' ? '#ffb07a' : zone === 'frost' ? '#dff4ff' : zone === 'umbra' ? '#c58cff' : '#ffe0a8'), Math.min(1, dt * 0.8));
  }

  return {
    heightAt, weights, zoneAt, colliders, poi, waypoints, npcSpawns, monsterSpawns,
    settlements, ruinSpots, bossPos: BOSS, hub: HUB, update, scene,
    bossArena: { x: BOSS.x, z: BOSS.z },
    zoneFog: ZONES,
  };
}

@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;600;700&family=Inter:wght@300;400;500;600&display=swap');

:root {
  --ink: #080c11;
  --ink-2: #0e141c;
  --panel: rgba(11, 16, 23, 0.83);
  --panel-solid: #10161f;
  --gold: #e6c17a;
  --gold-soft: #b9975a;
  --gold-dim: rgba(230, 193, 122, 0.22);
  --text: #ece7db;
  --muted: #98a2ad;
  --hp: #cf5b4a;
  --hp-2: #f08a5a;
  --mp: #4a8fc8;
  --mp-2: #7fd4f0;
  --xp: #d8b45a;
  --copper: #c9804f;
  --iron: #c2ced9;
  --gold-r: #f5c451;
  --diamond: #74e7f7;
  --adamantite: #c58cff;
  --serif: 'Cinzel', 'Palatino Linotype', Georgia, serif;
  --sans: 'Inter', system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden; background: var(--ink); color: var(--text); font-family: var(--sans); }
body { user-select: none; -webkit-user-select: none; }
canvas#scene { position: fixed; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }
.hidden { display: none !important; }
button { font-family: inherit; color: inherit; cursor: pointer; border: none; background: none; }
em { font-style: normal; }

/* ================= atmosphere overlays ================= */
#vignette { position: fixed; inset: 0; pointer-events: none; z-index: 2; background: radial-gradient(ellipse at 50% 42%, transparent 42%, rgba(4, 8, 12, 0.35) 78%, rgba(2, 5, 8, 0.75) 100%); }
#grain { position: fixed; inset: 0; pointer-events: none; z-index: 2; opacity: 0.10; mix-blend-mode: overlay; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.6'/%3E%3C/svg%3E"); }

/* ================= loading ================= */
.loading { position: fixed; inset: 0; z-index: 100; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 18px; background: radial-gradient(circle at 50% 45%, #17202e, #070a0f 70%); transition: opacity 0.7s ease; }
.loading.done { opacity: 0; pointer-events: none; }
.loading-emblem { font-size: 46px; color: var(--gold); text-shadow: 0 0 30px rgba(230, 193, 122, 0.8); animation: pulseGlow 2s infinite ease-in-out; }
.loading-title { font-family: var(--serif); font-size: 24px; letter-spacing: 0.22em; text-transform: uppercase; color: var(--gold); }
.loading-bar { width: 260px; height: 2px; background: rgba(230, 193, 122, 0.14); overflow: hidden; }
.loading-bar i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--gold-soft), var(--gold)); transition: width 0.35s ease; box-shadow: 0 0 12px var(--gold); }
.loading-text { font-size: 11px; color: var(--muted); letter-spacing: 0.18em; text-transform: uppercase; }
@keyframes pulseGlow { 0%, 100% { opacity: 0.55; transform: scale(0.96); } 50% { opacity: 1; transform: scale(1.05); } }

/* ================= title screen ================= */
#title-screen { position: fixed; inset: 0; z-index: 30; display: flex; flex-direction: column; transition: opacity 0.8s ease, transform 0.8s ease; }
#title-screen.gone { opacity: 0; pointer-events: none; transform: scale(1.02); }
.title-shade { position: absolute; inset: 0; pointer-events: none; background: linear-gradient(90deg, rgba(5, 9, 14, 0.94) 0%, rgba(6, 11, 17, 0.82) 36%, rgba(6, 11, 17, 0.36) 62%, rgba(6, 11, 17, 0.68) 100%), linear-gradient(0deg, rgba(4, 7, 11, 0.92) 0%, transparent 38%), radial-gradient(circle at 72% 30%, rgba(230, 193, 122, 0.08), transparent 50%); }
.title-inner { position: relative; z-index: 2; flex: 1; display: grid; grid-template-columns: minmax(420px, 1.05fr) minmax(470px, 0.95fr); gap: 40px; padding: clamp(24px, 4.4vw, 72px) clamp(22px, 4vw, 64px) 30px; min-height: 0; }
.title-left { display: flex; flex-direction: column; justify-content: center; max-width: 640px; animation: fadeUp 1s ease both; }
.title-eyebrow { display: flex; align-items: center; gap: 12px; font-size: 9px; letter-spacing: 0.4em; color: var(--gold); text-transform: uppercase; margin-bottom: 22px; opacity: 0.9; }
.title-eyebrow span { width: 32px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold)); }
.title-eyebrow span:last-child { background: linear-gradient(90deg, var(--gold), transparent); }
.game-title { font-family: var(--serif); font-weight: 700; font-size: clamp(44px, 6.2vw, 92px); line-height: 0.92; letter-spacing: 0.02em; margin: 0; color: #f3ecdc; text-shadow: 0 4px 40px rgba(0, 0, 0, 0.7); }
.game-title em { font-style: normal; display: inline-block; color: var(--gold); font-size: 0.63em; letter-spacing: 0.14em; margin-top: 8px; text-shadow: 0 0 40px rgba(230, 193, 122, 0.35); }
.title-sub { color: #c4c8c6; font-size: clamp(12px, 1.05vw, 15px); line-height: 1.75; margin: 26px 0 30px; font-weight: 300; max-width: 440px; }
.title-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-bottom: 40px; }
.btn { position: relative; padding: 14px 26px; font-size: 11px; font-weight: 600; letter-spacing: 0.2em; text-transform: uppercase; transition: all 0.22s ease; border: 1px solid transparent; border-radius: 2px; }
.btn-primary { color: #12100a; background: linear-gradient(135deg, #f0d69b, #c8a25c); box-shadow: 0 6px 30px rgba(230, 193, 122, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.45); }
.btn-primary:hover { background: linear-gradient(135deg, #ffeab8, #dcb670); box-shadow: 0 8px 36px rgba(230, 193, 122, 0.4); transform: translateY(-1px); }
.btn-primary:disabled { opacity: 0.35; cursor: default; transform: none; box-shadow: none; }
.btn-ghost { color: var(--gold); border-color: var(--gold-dim); background: rgba(12, 18, 26, 0.5); }
.btn-ghost:hover { border-color: var(--gold-soft); background: rgba(230, 193, 122, 0.08); }
.title-meta { display: flex; gap: clamp(16px, 2.6vw, 42px); border-top: 1px solid rgba(230, 193, 122, 0.16); padding-top: 18px; }
.title-meta div { display: flex; flex-direction: column; gap: 3px; }
.title-meta b { font-family: var(--serif); font-size: 17px; color: var(--gold); font-weight: 600; }
.title-meta span { font-size: 8px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--muted); }
.title-right { display: flex; flex-direction: column; justify-content: center; min-height: 0; animation: fadeUp 1s 0.15s ease both; }
.class-select-head { margin-bottom: 14px; }
.class-select-head h2 { font-family: var(--serif); font-size: clamp(18px, 2vw, 24px); margin: 0 0 5px; font-weight: 600; letter-spacing: 0.06em; color: #f0e8d8; }
.class-select-head p { margin: 0; color: var(--muted); font-size: 11px; font-weight: 300; }
.class-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; overflow-y: auto; padding: 2px; max-height: min(46vh, 430px); scrollbar-width: thin; }
.class-card { position: relative; display: flex; gap: 11px; padding: 11px 12px; background: linear-gradient(135deg, rgba(17, 24, 33, 0.86), rgba(10, 15, 21, 0.9)); border: 1px solid rgba(255, 255, 255, 0.07); border-radius: 3px; text-align: left; transition: all 0.18s ease; overflow: hidden; }
.class-card::before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 2px; background: var(--jc, var(--gold)); opacity: 0.4; transition: opacity 0.2s; }
.class-card:hover { border-color: rgba(230, 193, 122, 0.3); transform: translateY(-1px); background: linear-gradient(135deg, rgba(24, 33, 44, 0.92), rgba(12, 18, 25, 0.95)); }
.class-card.selected { border-color: var(--jc); background: linear-gradient(135deg, rgba(32, 40, 48, 0.96), rgba(14, 20, 27, 0.98)); box-shadow: 0 0 26px -6px var(--jc), inset 0 0 26px -18px var(--jc); }
.class-card.selected::before { opacity: 1; }
.class-icon { flex: 0 0 36px; height: 36px; border-radius: 50%; display: grid; place-items: center; font-size: 17px; color: var(--jc); background: radial-gradient(circle, rgba(255, 255, 255, 0.07), transparent 70%), rgba(0, 0, 0, 0.3); border: 1px solid color-mix(in srgb, var(--jc) 35%, transparent); }
.class-info { min-width: 0; flex: 1; }
.class-info b { display: block; font-family: var(--serif); font-size: 13px; letter-spacing: 0.04em; color: #ece4d4; margin-bottom: 1px; }
.class-info em { display: block; font-size: 8px; color: var(--muted); letter-spacing: 0.08em; text-transform: uppercase; margin-bottom: 6px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.class-bars { display: flex; gap: 3px; height: 3px; }
.class-bars i { height: 100%; flex: 1; background: rgba(255, 255, 255, 0.1); border-radius: 2px; overflow: hidden; }
.class-bars i b { display: block; height: 100%; background: var(--jc); }
.class-select-foot { margin-top: 14px; padding-top: 14px; border-top: 1px solid rgba(230, 193, 122, 0.15); display: flex; align-items: flex-end; gap: 14px; justify-content: space-between; }
.class-detail { font-size: 10px; color: #aab2b8; line-height: 1.65; min-height: 34px; flex: 1; font-weight: 300; }
.class-detail b { color: var(--gold); font-weight: 500; }
.btn-embark { padding: 13px 30px; white-space: nowrap; }
.title-footer { position: relative; z-index: 2; display: flex; justify-content: space-between; align-items: center; padding: 14px clamp(22px, 4vw, 64px); border-top: 1px solid rgba(255, 255, 255, 0.06); font-size: 9px; color: #7b848d; letter-spacing: 0.08em; }
.sound-toggle { font-size: 9px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--muted); padding: 6px 12px; border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 20px; transition: all 0.2s; }
.sound-toggle:hover { color: var(--gold); border-color: var(--gold-dim); }
@keyframes fadeUp { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: translateY(0); } }

/* ================= HUD ================= */
#hud { position: fixed; inset: 0; z-index: 10; pointer-events: none; }
#hud > * { pointer-events: none; }
#hud button, #hud .hud-btn { pointer-events: auto; }
.hud-top { position: absolute; top: max(12px, env(safe-area-inset-top)); left: max(14px, env(safe-area-inset-left)); right: max(14px, env(safe-area-inset-right)); display: flex; justify-content: space-between; align-items: flex-start; gap: 14px; }

.player-panel { display: flex; gap: 10px; padding: 10px 14px 10px 10px; background: linear-gradient(135deg, rgba(12, 18, 26, 0.9), rgba(8, 12, 18, 0.78)); border: 1px solid var(--gold-dim); border-radius: 3px; backdrop-filter: blur(12px); box-shadow: 0 10px 40px rgba(0, 0, 0, 0.35); min-width: 268px; }
.player-panel::after { content: ''; position: absolute; }
.portrait { position: relative; width: 52px; height: 52px; flex: 0 0 52px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.12), transparent 60%), rgba(0, 0, 0, 0.35); border: 1px solid var(--gold-dim); display: grid; place-items: center; }
#portrait-icon { font-size: 22px; filter: drop-shadow(0 0 8px rgba(230, 193, 122, 0.5)); }
.portrait i { position: absolute; inset: -3px; border-radius: 50%; border: 1px solid transparent; border-top-color: var(--gold); border-right-color: rgba(230, 193, 122, 0.2); animation: spin 9s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
.player-info { flex: 1; min-width: 168px; }
.player-name-row { display: flex; align-items: baseline; gap: 8px; margin-bottom: 5px; }
.player-name-row span { font-family: var(--serif); font-size: 14px; color: #f0e7d6; letter-spacing: 0.04em; }
.player-name-row em { font-size: 8px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--gold); opacity: 0.8; }
.level-row { display: flex; align-items: center; gap: 6px; margin-bottom: 5px; }
.level-row > span:first-child { font-size: 8px; color: var(--gold); letter-spacing: 0.08em; min-width: 26px; }
.tiny { font-size: 7px; color: var(--muted); min-width: 38px; text-align: right; }
.bar { position: relative; height: 9px; background: rgba(0, 0, 0, 0.55); border: 1px solid rgba(255, 255, 255, 0.07); border-radius: 2px; overflow: hidden; margin-bottom: 3px; }
.bar i { display: block; height: 100%; width: 100%; transition: width 0.3s ease; position: relative; }
.bar b { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 7px; font-weight: 500; letter-spacing: 0.06em; color: rgba(255, 255, 255, 0.88); text-shadow: 0 1px 2px rgba(0, 0, 0, 0.7); }
.bar.hp i { background: linear-gradient(90deg, #a33a35, var(--hp), var(--hp-2)); }
.bar.mp i { background: linear-gradient(90deg, #2c5f8a, var(--mp), var(--mp-2)); }
.bar.xp { height: 3px; flex: 1; margin: 0; }
.bar.xp i { background: linear-gradient(90deg, #8a6a2a, var(--xp)); }
.bar.boss { height: 12px; }
.bar.boss i { background: linear-gradient(90deg, #6a2030, #c0475a, #ff8a6a); }

.quest-tracker { flex: 0 1 300px; background: linear-gradient(135deg, rgba(12, 18, 26, 0.82), rgba(8, 12, 18, 0.6)); border-left: 2px solid var(--gold); padding: 9px 13px; backdrop-filter: blur(8px); border-radius: 0 3px 3px 0; margin-top: 4px; }
.qt-label { font-size: 7px; letter-spacing: 0.24em; color: var(--gold); opacity: 0.75; margin-bottom: 3px; }
.qt-title { font-family: var(--serif); font-size: 13px; color: #f0e7d6; margin-bottom: 3px; letter-spacing: 0.03em; }
.qt-obj { font-size: 9.5px; line-height: 1.5; color: #b4bcc3; font-weight: 300; }
.side-quests { margin-top: 7px; padding-top: 6px; border-top: 1px solid rgba(255, 255, 255, 0.07); display: flex; flex-direction: column; gap: 4px; }
.side-quest-item { font-size: 8px; color: #98a3ab; display: flex; gap: 6px; align-items: center; }
.side-quest-item b { color: var(--gold); font-weight: 500; }
.side-quest-item i { width: 3px; height: 3px; border-radius: 50%; background: var(--gold); flex: 0 0 3px; }

.hud-right { display: flex; flex-direction: column; align-items: flex-end; gap: 8px; }
.minimap-wrap { position: relative; width: 168px; height: 168px; border-radius: 50%; overflow: hidden; border: 1px solid var(--gold-dim); box-shadow: 0 8px 34px rgba(0, 0, 0, 0.45), inset 0 0 30px rgba(0, 0, 0, 0.5); background: #0a0f14; }
#minimap { width: 100%; height: 100%; display: block; }
.minimap-ring { position: absolute; inset: 5px; border-radius: 50%; border: 1px solid rgba(230, 193, 122, 0.15); pointer-events: none; }
.zone-chip { position: absolute; bottom: 6px; left: 50%; transform: translateX(-50%); font-size: 7px; letter-spacing: 0.14em; text-transform: uppercase; color: #e8dfcd; background: rgba(8, 12, 17, 0.78); padding: 3px 8px; border-radius: 10px; white-space: nowrap; border: 1px solid rgba(255, 255, 255, 0.08); }
.compass { position: absolute; top: 3px; left: 50%; transform: translateX(-50%); font-size: 7px; color: var(--gold); opacity: 0.7; }
.hud-buttons { display: flex; gap: 4px; }
.hud-btn { width: 46px; padding: 6px 2px 5px; display: flex; flex-direction: column; align-items: center; gap: 1px; background: rgba(10, 15, 21, 0.82); border: 1px solid rgba(230, 193, 122, 0.16); border-radius: 3px; backdrop-filter: blur(8px); transition: all 0.18s; }
.hud-btn span { font-size: 14px; color: var(--gold); line-height: 1; }
.hud-btn em { font-size: 6.5px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted); }
.hud-btn:hover { border-color: var(--gold-soft); background: rgba(230, 193, 122, 0.1); transform: translateY(-1px); }

.location-banner { position: absolute; top: 22%; left: 50%; transform: translate(-50%, -8px); text-align: center; opacity: 0; transition: all 1s ease; }
.location-banner.show { opacity: 1; transform: translate(-50%, 0); }
.location-banner span { display: block; font-family: var(--serif); font-size: clamp(20px, 3vw, 34px); letter-spacing: 0.22em; text-transform: uppercase; color: rgba(255, 250, 235, 0.94); text-shadow: 0 2px 30px rgba(0, 0, 0, 0.9); }
.location-banner em { display: block; font-size: 9px; color: var(--gold); letter-spacing: 0.3em; text-transform: uppercase; margin-top: 5px; }

.boss-bar { position: absolute; top: max(16px, env(safe-area-inset-top)); left: 50%; transform: translateX(-50%); width: min(540px, 52vw); z-index: 5; }
.boss-name { display: flex; justify-content: center; align-items: baseline; gap: 10px; margin-bottom: 5px; }
.boss-name span { font-family: var(--serif); font-size: 15px; letter-spacing: 0.12em; color: #ffd9c8; text-shadow: 0 2px 16px #000; }
.boss-name em { font-size: 8px; color: var(--gold); letter-spacing: 0.16em; text-transform: uppercase; }

.log-feed { position: absolute; left: max(16px, env(safe-area-inset-left)); bottom: 128px; display: flex; flex-direction: column-reverse; gap: 3px; max-width: 330px; }
.log-line { font-size: 9.5px; color: #b8c0c6; text-shadow: 0 1px 4px #000; padding: 3px 8px; background: rgba(6, 10, 14, 0.5); border-left: 1px solid rgba(230, 193, 122, 0.4); animation: logIn 0.35s ease both; }
.log-line.gold { color: var(--gold); }
.log-line.danger { color: #ff9a8a; }
.log-line.good { color: #9fe0a0; }
@keyframes logIn { from { opacity: 0; transform: translateX(-8px); } to { opacity: 1; transform: none; } }

.hud-bottom { position: absolute; left: 0; right: 0; bottom: max(14px, env(safe-area-inset-bottom)); display: flex; align-items: flex-end; justify-content: center; }
.action-dock { display: flex; flex-direction: column; align-items: center; gap: 10px; transition: transform 0.2s; }
.interact-prompt { display: flex; align-items: center; gap: 8px; background: rgba(10, 15, 21, 0.9); border: 1px solid var(--gold-dim); padding: 6px 14px 6px 6px; border-radius: 24px; backdrop-filter: blur(8px); animation: promptIn 0.25s ease both; box-shadow: 0 6px 26px rgba(0, 0, 0, 0.5); }
.interact-prompt b { width: 24px; height: 24px; border-radius: 50%; display: grid; place-items: center; background: rgba(230, 193, 122, 0.14); border: 1px solid var(--gold-soft); color: var(--gold); font-size: 10px; }
.interact-prompt span { font-size: 10px; letter-spacing: 0.06em; color: #e6e1d5; }
@keyframes promptIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
.skillbar { display: flex; align-items: flex-end; gap: 7px; padding: 8px 12px; background: linear-gradient(180deg, rgba(12, 17, 24, 0.72), rgba(8, 12, 17, 0.9)); border: 1px solid rgba(230, 193, 122, 0.18); border-radius: 3px; backdrop-filter: blur(14px); box-shadow: 0 14px 44px rgba(0, 0, 0, 0.5); }
.skill-btn { position: relative; width: 52px; height: 56px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; background: rgba(255, 255, 255, 0.035); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 3px; transition: all 0.15s; overflow: hidden; }
.skill-btn:hover { background: rgba(230, 193, 122, 0.09); border-color: var(--gold-dim); }
.skill-btn:active { transform: scale(0.96); }
.skill-icon { font-size: 20px; line-height: 1; filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.5)); }
.skill-btn em { font-size: 6.5px; letter-spacing: 0.06em; color: #aab2b8; text-transform: uppercase; max-width: 48px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.skill-key { position: absolute; top: 2px; left: 4px; font-size: 7px; color: var(--gold); opacity: 0.7; }
.skill-cd { position: absolute; inset: 0; background: rgba(3, 6, 10, 0.72); transform-origin: bottom; pointer-events: none; }
.skill-btn.no-mp { border-color: rgba(120, 150, 200, 0.35); }
.potion-btn { width: 46px; }
.potion-count { position: absolute; bottom: 3px; right: 5px; font-size: 8px; color: var(--gold); }
.attack-btn { width: 74px; height: 74px; border-radius: 50%; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px; background: radial-gradient(circle at 35% 30%, #f5e3b0, #c8a25c 45%, #6a5228); color: #1a150c; border: 2px solid rgba(255, 240, 200, 0.5); box-shadow: 0 0 0 4px rgba(230, 193, 122, 0.12), 0 8px 30px rgba(230, 193, 122, 0.3); transition: all 0.12s; }
.attack-btn span { font-size: 26px; line-height: 1; }
.attack-btn em { font-size: 7px; letter-spacing: 0.1em; text-transform: uppercase; font-weight: 600; }
.attack-btn:hover { transform: scale(1.04); box-shadow: 0 0 0 5px rgba(230, 193, 122, 0.2), 0 10px 40px rgba(230, 193, 122, 0.4); }
.attack-btn:active { transform: scale(0.93); }

.joystick { position: absolute; left: max(26px, env(safe-area-inset-left)); bottom: 0; width: 128px; height: 128px; display: none; touch-action: none; }
.joy-base { position: absolute; inset: 8px; border-radius: 50%; border: 1px solid rgba(230, 193, 122, 0.3); background: radial-gradient(circle, rgba(12, 18, 26, 0.55), rgba(8, 12, 17, 0.75)); box-shadow: inset 0 0 30px rgba(0, 0, 0, 0.5); }
.joy-knob { position: absolute; width: 52px; height: 52px; left: 50%; top: 50%; transform: translate(-50%, -50%); border-radius: 50%; background: radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.25), rgba(230, 193, 122, 0.25)); border: 1px solid rgba(230, 193, 122, 0.5); box-shadow: 0 4px 18px rgba(0, 0, 0, 0.4); }
.touch-extra { position: absolute; right: max(18px, env(safe-area-inset-right)); bottom: 0; display: flex; flex-direction: column; gap: 8px; }
.round-btn { width: 46px; height: 46px; border-radius: 50%; display: none; place-items: center; font-size: 16px; color: var(--gold); background: rgba(10, 15, 21, 0.82); border: 1px solid var(--gold-dim); backdrop-filter: blur(8px); }
body.touch .joystick { display: block; }
body.touch .round-btn { display: grid; }

.tutorial-tip { position: absolute; left: 50%; bottom: 118px; transform: translateX(-50%); display: flex; gap: 10px; align-items: center; padding: 9px 16px 9px 10px; background: rgba(10, 15, 21, 0.9); border: 1px solid var(--gold-dim); border-radius: 3px; backdrop-filter: blur(10px); max-width: 390px; animation: promptIn 0.4s ease both; box-shadow: 0 10px 36px rgba(0, 0, 0, 0.5); }
.tip-gem { width: 30px; height: 30px; flex: 0 0 30px; display: grid; place-items: center; border-radius: 50%; background: radial-gradient(circle, rgba(230, 193, 122, 0.2), transparent 70%); color: var(--gold); border: 1px solid var(--gold-dim); }
.tutorial-tip b { display: block; font-size: 9px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--gold); margin-bottom: 2px; }
.tutorial-tip span { font-size: 10px; color: #c8ccc9; line-height: 1.45; display: block; }

.toasts { position: absolute; top: 88px; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 5px; pointer-events: none; z-index: 12; }
.toast { padding: 7px 16px; background: rgba(10, 15, 21, 0.92); border: 1px solid var(--gold-dim); border-radius: 2px; font-size: 10px; color: #e8e2d4; letter-spacing: 0.04em; display: flex; gap: 8px; align-items: center; animation: toastIn 0.3s ease both; box-shadow: 0 6px 24px rgba(0, 0, 0, 0.45); backdrop-filter: blur(8px); }
.toast.gold { border-color: rgba(230, 193, 122, 0.5); color: var(--gold); }
.toast.rarity { border-color: var(--rc, var(--gold)); color: var(--rc, var(--gold)); }
.toast.out { animation: toastOut 0.4s ease both; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-8px) scale(0.97); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-8px); } }

.labels { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.lbl { position: absolute; transform: translate(-50%, -100%); text-align: center; white-space: nowrap; will-change: transform; }
.lbl.npc span { font-size: 9px; letter-spacing: 0.08em; color: #efe8d8; text-shadow: 0 1px 4px #000, 0 0 12px #000; }
.lbl.npc .npc-role { display: block; font-size: 6.5px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--gold); opacity: 0.85; }
.lbl.npc .marker { display: block; width: 16px; height: 16px; margin: 0 auto 2px; font-size: 12px; color: var(--gold); text-shadow: 0 0 10px rgba(230, 193, 122, 0.8); animation: bob 1.8s infinite ease-in-out; }
.lbl.npc.quest .marker { color: #ffe08a; font-size: 15px; }
.lbl.enemy .ename { font-size: 8px; color: #ffd6c8; text-shadow: 0 1px 4px #000; display: block; margin-bottom: 2px; }
.lbl.enemy .ebar { width: 46px; height: 3px; background: rgba(0, 0, 0, 0.7); border: 1px solid rgba(0, 0, 0, 0.5); margin: 0 auto; }
.lbl.enemy .ebar i { display: block; height: 100%; background: linear-gradient(90deg, #a33a35, #e07a5a); }
.lbl.enemy.elite .ename { color: #ffcf6a; }
.lbl.enemy.boss { display: none; }
@keyframes bob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-3px); } }

.floaters { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.floater { position: absolute; transform: translate(-50%, -50%); font-weight: 600; font-size: 15px; color: #ffe0a0; text-shadow: 0 2px 6px #000, 0 0 10px rgba(0, 0, 0, 0.6); animation: floatUp 1s ease-out forwards; will-change: transform, opacity; }
.floater.crit { font-size: 21px; color: #ffd479; }
.floater.heal { color: #9fe0a0; }
.floater.player-hit { color: #ff8a7a; }
.floater.xp { color: #b8e0ff; font-size: 12px; }
.floater.loot { color: #d8c8ff; font-size: 11px; font-weight: 400; }
@keyframes floatUp { 0% { opacity: 0; transform: translate(-50%, -40%) scale(0.8); } 15% { opacity: 1; transform: translate(-50%, -60%) scale(1.05); } 100% { opacity: 0; transform: translate(-50%, -160%) scale(1); } }

.damage-flash { position: absolute; inset: 0; pointer-events: none; box-shadow: inset 0 0 130px rgba(180, 30, 20, 0); transition: box-shadow 0.3s ease; }
.damage-flash.hit { box-shadow: inset 0 0 130px rgba(180, 30, 20, 0.5); transition: none; }
.zone-fade { position: fixed; inset: 0; pointer-events: none; background: #06090d; opacity: 0; transition: opacity 0.5s ease; z-index: 25; }
.zone-fade.on { opacity: 1; }

/* ================= modal ================= */
#modal-root { position: fixed; inset: 0; z-index: 40; pointer-events: none; }
.modal-backdrop { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; padding: 22px; background: rgba(4, 7, 11, 0.55); backdrop-filter: blur(7px); pointer-events: auto; animation: fadeIn 0.22s ease both; z-index: 1; }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
.modal { position: relative; width: min(940px, 94vw); max-height: 88vh; display: flex; flex-direction: column; background: linear-gradient(160deg, rgba(17, 24, 33, 0.98), rgba(9, 13, 19, 0.99)); border: 1px solid rgba(230, 193, 122, 0.26); border-radius: 3px; box-shadow: 0 30px 100px rgba(0, 0, 0, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.05); animation: modalIn 0.26s cubic-bezier(0.2, 0.9, 0.3, 1.1) both; }
.modal::before { content: ''; position: absolute; inset: 6px; border: 1px solid rgba(230, 193, 122, 0.08); pointer-events: none; }
@keyframes modalIn { from { opacity: 0; transform: translateY(14px) scale(0.985); } to { opacity: 1; transform: none; } }
.modal-head { display: flex; justify-content: space-between; align-items: flex-start; padding: 22px 26px 15px; border-bottom: 1px solid rgba(230, 193, 122, 0.14); flex: 0 0 auto; }
.modal-title { font-family: var(--serif); font-size: clamp(18px, 2.4vw, 24px); letter-spacing: 0.08em; color: #f2ead8; margin: 0; font-weight: 600; }
.modal-sub { margin: 4px 0 0; font-size: 10px; color: var(--muted); letter-spacing: 0.04em; font-weight: 300; max-width: 620px; }
.modal-close { width: 32px; height: 32px; flex: 0 0 32px; border: 1px solid rgba(255, 255, 255, 0.12); border-radius: 50%; color: #c8c8c0; font-size: 16px; display: grid; place-items: center; transition: all 0.18s; }
.modal-close:hover { border-color: var(--gold); color: var(--gold); transform: rotate(90deg); }
.modal-body { padding: 18px 26px 24px; overflow-y: auto; scrollbar-width: thin; scrollbar-color: rgba(230, 193, 122, 0.3) transparent; }
.modal-body::-webkit-scrollbar { width: 6px; }
.modal-body::-webkit-scrollbar-thumb { background: rgba(230, 193, 122, 0.3); border-radius: 3px; }
.modal-foot { padding: 14px 26px; border-top: 1px solid rgba(230, 193, 122, 0.12); display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; flex: 0 0 auto; }
.gold-text { color: var(--gold); }
.muted { color: var(--muted); }
.tab-row { display: flex; gap: 4px; margin-bottom: 16px; flex-wrap: wrap; }
.tab { padding: 7px 16px; font-size: 9px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--muted); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 2px; transition: all 0.18s; }
.tab:hover { color: var(--text); border-color: rgba(255, 255, 255, 0.2); }
.tab.active { color: #12100a; background: linear-gradient(135deg, #e8cf96, #c8a25c); border-color: transparent; font-weight: 600; }

/* inventory */
.inv-layout { display: grid; grid-template-columns: 250px 1fr; gap: 22px; }
.equip-col { display: flex; flex-direction: column; gap: 10px; }
.paper-doll { position: relative; height: 240px; border: 1px solid rgba(230, 193, 122, 0.14); background: radial-gradient(circle at 50% 40%, rgba(230, 193, 122, 0.07), transparent 65%), rgba(0, 0, 0, 0.18); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; overflow: hidden; }
.paper-doll .pd-icon { font-size: 62px; filter: drop-shadow(0 8px 24px rgba(230, 193, 122, 0.35)); }
.paper-doll .pd-name { font-family: var(--serif); font-size: 13px; color: var(--gold); letter-spacing: 0.1em; }
.paper-doll .pd-sub { font-size: 8px; letter-spacing: 0.18em; text-transform: uppercase; color: var(--muted); }
.paper-doll::after { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(0deg, transparent, transparent 12px, rgba(230, 193, 122, 0.04) 12px, rgba(230, 193, 122, 0.04) 13px); pointer-events: none; }
.equip-slot { display: flex; align-items: center; gap: 10px; padding: 9px 11px; border: 1px solid rgba(255, 255, 255, 0.08); background: rgba(255, 255, 255, 0.025); border-radius: 2px; text-align: left; width: 100%; }
.equip-slot:hover { border-color: var(--gold-dim); }
.equip-slot .es-label { font-size: 7px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--muted); display: block; margin-bottom: 1px; }
.equip-slot .es-name { font-size: 10px; color: #e8e2d4; display: block; max-width: 170px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.equip-slot .es-icon { width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; font-size: 14px; background: rgba(0, 0, 0, 0.3); border: 1px solid var(--ec, rgba(255, 255, 255, 0.1)); color: var(--ec, #fff); }
.stat-list { display: grid; grid-template-columns: 1fr 1fr; gap: 5px 14px; margin-top: 8px; font-size: 9px; }
.stat-list div { display: flex; justify-content: space-between; border-bottom: 1px dotted rgba(255, 255, 255, 0.08); padding-bottom: 3px; }
.stat-list span { color: var(--muted); }
.stat-list b { color: var(--text); font-weight: 500; }
.inv-main { min-width: 0; }
.inv-toolbar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; font-size: 9px; color: var(--muted); }
.item-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(88px, 1fr)); gap: 6px; max-height: 400px; overflow-y: auto; padding-right: 2px; }
.item-card { position: relative; aspect-ratio: 0.86; padding: 9px 7px 7px; background: linear-gradient(160deg, color-mix(in srgb, var(--rc, #888) 10%, rgba(14, 20, 28, 0.9)), rgba(10, 15, 21, 0.95)); border: 1px solid color-mix(in srgb, var(--rc, #888) 38%, transparent); border-radius: 2px; display: flex; flex-direction: column; align-items: center; gap: 3px; transition: all 0.15s; text-align: center; }
.item-card:hover { transform: translateY(-2px); box-shadow: 0 6px 18px rgba(0, 0, 0, 0.4); border-color: var(--rc); }
.item-card .ii { font-size: 22px; line-height: 1; filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.6)); }
.item-card .in { font-size: 8px; color: #ddd8ca; line-height: 1.25; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; min-height: 19px; }
.item-card .iq { position: absolute; top: 4px; right: 5px; font-size: 7px; color: var(--gold); }
.item-card .irar { position: absolute; top: 0; left: 0; width: 3px; height: 100%; background: var(--rc); opacity: 0.8; }
.item-card.equipped { outline: 1px solid var(--gold); outline-offset: 1px; }
.empty-note { padding: 40px 20px; text-align: center; color: var(--muted); font-size: 10px; border: 1px dashed rgba(255, 255, 255, 0.1); border-radius: 2px; }

.item-detail { margin-top: 12px; padding: 12px 14px; border: 1px solid rgba(230, 193, 122, 0.16); background: rgba(255, 255, 255, 0.025); display: flex; gap: 12px; align-items: center; min-height: 64px; }
.item-detail .id-icon { width: 42px; height: 42px; display: grid; place-items: center; font-size: 22px; border: 1px solid var(--rc, var(--gold-dim)); background: rgba(0, 0, 0, 0.25); }
.item-detail .id-body { flex: 1; }
.item-detail .id-name { font-family: var(--serif); font-size: 13px; color: var(--rc, var(--gold)); margin-bottom: 2px; }
.item-detail .id-desc { font-size: 9px; color: var(--muted); line-height: 1.5; }
.item-detail .id-actions { display: flex; gap: 6px; }

/* shop */
.shop-head { display: flex; justify-content: space-between; gap: 14px; align-items: flex-start; margin-bottom: 16px; }
.shop-tag { font-size: 10px; color: var(--muted); font-style: italic; font-family: var(--serif); max-width: 460px; line-height: 1.6; }
.wallet { display: flex; gap: 14px; font-size: 10px; white-space: nowrap; }
.wallet b { color: var(--gold); }
.shop-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 8px; margin-bottom: 18px; }
.shop-item { display: flex; align-items: center; gap: 11px; padding: 11px; border: 1px solid color-mix(in srgb, var(--rc, #888) 30%, transparent); background: rgba(255, 255, 255, 0.025); border-radius: 2px; }
.shop-item .si-icon { width: 40px; height: 40px; flex: 0 0 40px; display: grid; place-items: center; font-size: 20px; background: rgba(0, 0, 0, 0.3); border: 1px solid color-mix(in srgb, var(--rc) 40%, transparent); color: var(--rc); }
.shop-item .si-body { flex: 1; min-width: 0; }
.shop-item .si-name { font-size: 10px; color: var(--rc, #e8e2d4); font-weight: 500; line-height: 1.3; }
.shop-item .si-desc { font-size: 8px; color: var(--muted); line-height: 1.4; margin-top: 2px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.shop-item .si-buy { text-align: right; flex: 0 0 auto; }
.shop-item .si-price { display: block; font-size: 9px; color: var(--gold); margin-bottom: 4px; }
.mini-btn { padding: 4px 10px; font-size: 8px; letter-spacing: 0.1em; text-transform: uppercase; border: 1px solid var(--gold-dim); color: var(--gold); background: rgba(230, 193, 122, 0.06); border-radius: 2px; transition: all 0.15s; white-space: nowrap; }
.mini-btn:hover { background: rgba(230, 193, 122, 0.16); border-color: var(--gold); }
.mini-btn.danger { border-color: rgba(200, 90, 90, 0.3); color: #e8a090; }
.mini-btn.danger:hover { background: rgba(200, 90, 90, 0.12); border-color: #c86a5a; }
.mini-btn:disabled { opacity: 0.3; }
.section-title { font-size: 8px; letter-spacing: 0.24em; text-transform: uppercase; color: var(--gold); margin: 0 0 9px; display: flex; align-items: center; gap: 8px; }
.section-title::after { content: ''; flex: 1; height: 1px; background: rgba(230, 193, 122, 0.14); }

/* gacha */
.loom-hero { position: relative; height: 150px; margin-bottom: 18px; border: 1px solid rgba(230, 193, 122, 0.16); background: radial-gradient(circle at 50% 55%, rgba(155, 127, 192, 0.28), transparent 62%), radial-gradient(circle at 50% 55%, rgba(230, 193, 122, 0.1), transparent 45%), rgba(0, 0, 0, 0.25); display: flex; flex-direction: column; align-items: center; justify-content: center; overflow: hidden; }
.loom-hero::before { content: ''; position: absolute; width: 220px; height: 220px; border: 1px solid rgba(197, 140, 255, 0.18); border-radius: 50%; animation: spin 26s linear infinite; }
