266:   recalcStats() {
267:     if (!this.state) return;
268:     const s = this.state, job = JOBS[s.job];
269:     const oldMax = s.maxHp || job.hp;
270:     s.maxHp = Math.round(job.hp + (s.level - 1) * 19 + (s.armor?.def || 0) * 1.4);
271:     s.maxMp = Math.round(job.mp + (s.level - 1) * 9);
272:     s.atk = Math.round((job.atk + (s.level - 1) * 2.4 + (s.weapon?.atk || 0)) * 10) / 10;
273:     s.def = Math.round((job.def + (s.level - 1) * 1.6 + (s.armor?.def || 0)) * 10) / 10;
274:     s.hp = Math.min(s.hp, s.maxHp);
275:     s.mp = Math.min(s.mp, s.maxMp);
276:     if (s.maxHp > oldMax && s.hp > 0) s.hp = Math.min(s.maxHp, s.hp + (s.maxHp - oldMax));
277:   }
