293:       const k = e.key.toLowerCase();
294:       if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].includes(k)) e.preventDefault();
295:       if (this.mode !== 'play') return;
296:       if (k === 'escape') { if (this.modalOpen) this.closeModal(); return; }
297:       if (this.modalOpen) return;
298:       this.keys[k] = true;
299:       if (k === 'j') this.basicAttack();
300:       if (k === ' ') this.jump();
301:       if (k === 'e') this.doInteract();
302:       if (k === 'h') this.usePotion();
303:       if (k === 'i') this.openInventory();
304:       if (k === 'm') this.openMap();
305:       if (k === 'q') this.openJournal();
306:       if (k === 'g') this.openGacha();
307:       if (k === '?' || k === '/') this.openHelp();
308:       if (['1', '2', '3'].includes(k)) this.useSkill(Number(k) - 1);
309:     });
