313:     const c = this.canvas;
314:     c.addEventListener('pointerdown', (e) => {
315:       if (this.mode !== 'play' || this.modalOpen) return;
316:       this.drag = { id: e.pointerId, x: e.clientX, y: e.clientY, sx: e.clientX, sy: e.clientY, moved: false, t: performance.now(), type: e.pointerType };
317:       c.setPointerCapture(e.pointerId);
318:     });
319:     c.addEventListener('pointermove', (e) => {
320:       if (!this.drag || this.drag.id !== e.pointerId) return;
321:       const dx = e.clientX - this.drag.x, dy = e.clientY - this.drag.y;
322:       this.drag.x = e.clientX; this.drag.y = e.clientY;
323:       if (Math.abs(e.clientX - this.drag.sx) + Math.abs(e.clientY - this.drag.sy) > 5) this.drag.moved = true;
324:       this.cam.yaw -= dx * (e.pointerType === 'touch' ? 0.007 : 0.0048);
325:       this.cam.pitch = clamp(this.cam.pitch + dy * 0.0035, 0.06, 0.95);
326:       if (this.state && this.state.tutorial.step === 1) this.state.tutorial.rotated += Math.abs(dx) + Math.abs(dy);
327:     });
328:     c.addEventListener('pointerup', (e) => {
329:       if (!this.drag || this.drag.id !== e.pointerId) return;
330:       const d = this.drag; this.drag = null;
331:       if (!d.moved && d.type === 'mouse' && performance.now() - d.t < 450) this.basicAttack();
332:     });
333:     c.addEventListener('pointercancel', () => { this.drag = null; });
334:     c.addEventListener('wheel', (e) => {
335:       if (this.mode !== 'play' || this.modalOpen) return;
336:       e.preventDefault();
337:       this.cam.dist = clamp(this.cam.dist + Math.sign(e.deltaY) * 1.5, 7, 34);
338:     }, { passive: false });
