344:   bindJoystick() {
345:     const base = $('joystick');
346:     const knob = $('joy-knob');
347:     let id = null;
348:     const reset = () => { this.joy.x = 0; this.joy.z = 0; knob.style.transform = 'translate(-50%, -50%)'; };
349:     base.addEventListener('pointerdown', (e) => {
350:       e.stopPropagation();
351:       id = e.pointerId; base.setPointerCapture(id); this.audio.init();
352:     });
353:     base.addEventListener('pointermove', (e) => {
354:       if (e.pointerId !== id) return;
355:       const r = base.getBoundingClientRect();
356:       const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
357:       let dx = (e.clientX - cx) / (r.width * 0.36), dy = (e.clientY - cy) / (r.height * 0.36);
358:       const len = Math.hypot(dx, dy);
359:       if (len > 1) { dx /= len; dy /= len; }
360:       this.joy.x = dx; this.joy.z = dy;
361:       knob.style.transform = `translate(calc(-50% + ${dx * r.width * 0.3}px), calc(-50% + ${dy * r.height * 0.3}px))`;
362:     });
363:     const up = (e) => { if (e.pointerId === id) { id = null; reset(); } };
364:     base.addEventListener('pointerup', up);
365:     base.addEventListener('pointercancel', up);
366:   }
