400:   /* ---------------- loop ---------------- */
401:   loop() {
402:     const now = performance.now();
403:     const dt = Math.min(0.05, (now - this.lastT) / 1000);
404:     this.lastT = now;
405:     this.time += dt;
406:     if (this.mode === 'title') {
407:       this.titleT += dt;
408:       const a = this.titleT * 0.04;
409:       this.camera.position.set(Math.cos(a) * 148, 54 + Math.sin(a * 0.7) * 8, Math.sin(a) * 148);
410:       this.camera.lookAt(0, 18, 0);
411:       this.world.update(dt, this.time, this.camera, { x: 0, y: 4, z: 0 });
412:     } else if (this.state) {
413:       this.updatePlay(dt);
414:     }
415:     this.audio.tick(this.time);
416:     this.renderer.render(this.scene, this.camera);
417:   }
