419:   updatePlay(dt) {
420:     this.state.playtime += dt;
421:     this.updatePlayer(dt);
422:     if (!this.modalOpen) {
423:       this.updateEnemies(dt);
424:       this.updateCombatTimers(dt);
425:     }
426:     this.updateProjectiles(dt);
427:     this.updateEffects(dt);
428:     this.updateTimers(dt);
429:     this.updateCamera(dt);
430:     this.world.update(dt, this.time, this.camera, this.playerMesh.position);
431:     this.updateLabels();
432:     this.updateTargetRing();
433:     if (this.time - this.lastHud > 0.08) { this.lastHud = this.time; this.updateHUD(); }
434:     if (this.time - this.lastSave > 20) { this.lastSave = this.time; this.save(); }
435:     if (this.time - this.lastDistCheck > 0.4) { this.lastDistCheck = this.time; this.checkDiscovery(); }
436:     this.audio.setZone(this.currentZone());
437:   }
