439:   updatePlayer(dt) {
440:     if (!this.playerMesh) return;
441:     const s = this.state;
442:     this.attackCd = Math.max(0, this.attackCd - dt);
443:     this.hurtInvuln = Math.max(0, this.hurtInvuln - dt);
444:     this.combatT = Math.max(0, this.combatT - dt);
445:     this.attackAnimT = Math.max(0, this.attackAnimT - dt);
446:     this.castAnimT = Math.max(0, this.castAnimT - dt);
447:     for (const sk of this.skillCds) sk.cd = Math.max(0, sk.cd - dt);
448:     // regen
449:     if (this.combatT <= 0) {
450:       s.hp = Math.min(s.maxHp, s.hp + dt * (s.maxHp * 0.012));
451:       s.mp = Math.min(s.maxMp, s.mp + dt * (s.maxMp * 0.028));
452:     } else {
453:       s.mp = Math.min(s.maxMp, s.mp + dt * (s.maxMp * 0.012));
454:     }
455:     if (this.modalOpen) { this.playerMesh.userData.animate(this.time, 0, null, null); return; }
456: 
457:     const k = this.keys;
458:     let f = 0, r = 0;
459:     if (k['w'] || k['arrowup']) f += 1;
460:     if (k['s'] || k['arrowdown']) f -= 1;
461:     if (k['d'] || k['arrowright']) r += 1;
462:     if (k['a'] || k['arrowleft']) r -= 1;
463:     f += -this.joy.z; r += this.joy.x;
464:     const len = Math.hypot(f, r);
465:     let moving = 0;
466:     if (len > 0.05) {
467:       f /= len; r /= len;
468:       const sprint = (k['shift'] ? 1.45 : 1) * (this.guardUntil > this.time ? 0.8 : 1);
469:       const speed = JOBS[s.job].speed * sprint;
470:       const mx = (-Math.sin(this.cam.yaw) * f + Math.cos(this.cam.yaw) * r) * speed * dt;
471:       const mz = (-Math.cos(this.cam.yaw) * f - Math.sin(this.cam.yaw) * r) * speed * dt;
472:       s.pos.x += mx; s.pos.z += mz;
473:       s.stats.distance += Math.hypot(mx, mz);
474:       if (!s.tutorial.done && s.tutorial.step === 0) {
475:         s.tutorial.traveled += Math.hypot(mx, mz);
476:         if (s.tutorial.traveled > 22) this.advanceTutorial(1);
477:       }
478:       s.rotation = Math.atan2(mx, mz);
479:       moving = 1;
480:     }
481:     // bounds + buildings
482:     s.pos.x = clamp(s.pos.x, -WORLD_HALF + 70, WORLD_HALF - 70);
483:     s.pos.z = clamp(s.pos.z, -WORLD_HALF + 70, WORLD_HALF - 70);
484:     for (const c of this.world.colliders) {
485:       if (Math.abs(c.x - s.pos.x) > 30 || Math.abs(c.z - s.pos.z) > 30) continue;
486:       const dx = s.pos.x - c.x, dz = s.pos.z - c.z;
487:       const d = Math.hypot(dx, dz), min = c.r + 0.6;
488:       if (d < min) {
489:         const inv = d > 0.001 ? 1 / d : 0;
490:         s.pos.x = c.x + dx * inv * min;
491:         s.pos.z = c.z + dz * inv * min;
492:       }
493:     }
494:     // jump
495:     if (this.jumpY > 0 || this.vy > 0) {
496:       this.vy -= 19 * dt;
497:       this.jumpY = Math.max(0, this.jumpY + this.vy * dt);
498:       if (this.jumpY === 0) this.vy = 0;
499:     }
500:     const gy = this.ground(s.pos.x, s.pos.z);
501:     this.playerMesh.position.set(s.pos.x, gy + this.jumpY, s.pos.z);
502:     // smooth facing
503:     let d = s.rotation - this.playerMesh.rotation.y;
504:     d = ((d + Math.PI) % (Math.PI * 2) + Math.PI * 2) % (Math.PI * 2) - Math.PI;
505:     this.playerMesh.rotation.y += d * Math.min(1, dt * 14);
506:     const attackP = this.attackAnimT > 0 ? 1 - this.attackAnimT / 0.34 : null;
507:     const castP = this.castAnimT > 0 ? 1 - this.castAnimT / 0.45 : null;
508:     this.playerMesh.userData.animate(this.time, moving, attackP, castP);
509:     // guard bubble
510:     if (this.guardMesh) {
511:       this.guardMesh.visible = this.guardUntil > this.time;
512:       this.guardMesh.position.copy(this.playerMesh.position).add(new THREE.Vector3(0, 1.1, 0));
513:       this.guardMesh.rotation.y = this.time;
514:     }
515:     this.updateZone();
516:     this.checkTutorialProgress();
517:     this.updateInteractPrompt();
518:   }
