520:   /* ---------------- camera ---------------- */
521:   updateCamera(dt) {
522:     if (!this.playerMesh) return;
523:     const p = this.playerMesh.position;
524:     const target = this.camTarget;
525:     target.set(lerp(target.x || p.x, p.x, Math.min(1, dt * 10)), 0, lerp(target.z || p.z, p.z, Math.min(1, dt * 10)));
526:     target.y = p.y + 1.75;
527:     this.cam.ty = target.y;
528:     const cosP = Math.cos(this.cam.pitch);
529:     const dist = this.cam.dist;
530:     const desired = new THREE.Vector3(
531:       p.x + Math.sin(this.cam.yaw) * dist * cosP,
532:       p.y + 1.75 + Math.sin(this.cam.pitch) * dist,
533:       p.z + Math.cos(this.cam.yaw) * dist * cosP,
534:     );
535:     const terr = this.ground(desired.x, desired.z) + 1.4;
536:     if (desired.y < terr) desired.y = terr;
537:     if (this.camPos.lengthSq() === 0) this.camPos.copy(desired);
538:     this.camPos.lerp(desired, Math.min(1, dt * 8));
539:     this.camera.position.copy(this.camPos);
540:     if (this.shake > 0) {
541:       this.shake = Math.max(0, this.shake - dt);
542:       const a = this.shake * 0.55;
543:       this.camera.position.x += (Math.random() - 0.5) * a;
544:       this.camera.position.y += (Math.random() - 0.5) * a;
545:     }
546:     this.camera.lookAt(target);
547:   }
