571:   updateInteractPrompt() {
572:     if (this.modalOpen || !this.playerMesh) { $('interact-prompt').classList.add('hidden'); return; }
573:     const p = this.playerMesh.position;
574:     let near = null, best = 6;
575:     for (const n of this.npcs) {
576:       const d = Math.hypot(n.x - p.x, n.z - p.z);
577:       if (d < best) { best = d; near = { type: 'npc', obj: n, text: n.def.vendor ? `Trade with ${n.def.name}` : n.def.gacha ? 'Visit the Astral Loom' : `Speak with ${n.def.name}` }; }
578:     }
579:     for (const b of this.world.boards) {
580:       const d = Math.hypot(b.x - p.x, b.z - p.z);
581:       if (d < 4.5) near = { type: 'board', obj: b, text: 'Read the quest board' };
582:     }
583:     for (const wp of this.world.waypoints) {
584:       const d = Math.hypot(wp.x - p.x, wp.z - p.z);
585:       if (d < 5) near = { type: 'waypoint', obj: wp, text: wp.unlocked ? 'Open the world map' : 'Attune this waypoint' };
586:     }
587:     if (near) {
588:       $('interact-text').textContent = near.text;
589:       $('interact-prompt').classList.remove('hidden');
590:     } else {
591:       $('interact-prompt').classList.add('hidden');
592:     }
593:     this.near = near;
594:   }
