750:   updateLabels() {
751:     if (!this.playerMesh) return;
752:     const p = this.playerMesh.position;
753:     for (const n of this.npcs) {
754:       const d = Math.hypot(n.x - p.x, n.z - p.z);
755:       if (d > 110) { n.label.style.display = 'none'; continue; }
756:       const sp = this.project(n.mesh.position.clone().add(new THREE.Vector3(0, n.labelY, 0)));
757:       if (!sp || sp.z > 1) { n.label.style.display = 'none'; continue; }
758:       n.label.style.display = 'block';
759:       n.label.style.left = sp.x + 'px';
760:       n.label.style.top = sp.y + 'px';
761:       const isTarget = this.getMainTargetNpc() === n.id;
762:       const marker = n.label.querySelector('.marker');
763:       if (isTarget) { marker.textContent = '!'; n.label.classList.add('quest'); }
764:       else if (n.def.story && !this.state.flags['met_' + n.id]) { marker.textContent = '?'; n.label.classList.remove('quest'); }
765:       else { marker.textContent = ''; n.label.classList.remove('quest'); }
766:       // face near player
767:       if (d < 9) {
768:         const ang = Math.atan2(p.x - n.x, p.z - n.z);
769:         n.mesh.rotation.y = lerp(n.mesh.rotation.y, ang, 0.08);
770:       } else {
771:         n.mesh.rotation.y = lerp(n.mesh.rotation.y, n.baseRot, 0.03);
772:       }
773:       n.mesh.userData.animate(this.time + n.phase, 0, null, null);
774:     }
775:     for (const e of this.enemies) {
776:       if (!e.label) continue;
777:       if (e.dead || e.def.boss) { e.label.style.display = 'none'; continue; }
778:       const d = Math.hypot(e.mesh.position.x - p.x, e.mesh.position.z - p.z);
779:       if (d > 72) { e.label.style.display = 'none'; continue; }
780:       const sp = this.project(e.mesh.position.clone().add(new THREE.Vector3(0, e.labelY * (e.def.scale || 1), 0)));
781:       if (!sp || sp.z > 1) { e.label.style.display = 'none'; continue; }
782:       e.label.style.display = 'block';
783:       e.label.style.left = sp.x + 'px';
784:       e.label.style.top = sp.y + 'px';
785:       const bar = e.label.querySelector('.ebar i');
786:       if (bar) bar.style.width = Math.max(0, (e.hp / e.maxHp) * 100) + '%';
787:     }
788:   }
