894:   addItem(item, qty = 1, announce = false) {
895:     if (!this.state) return;
896:     const stack = ['loot', 'potion'].includes(item.kind);
897:     if (stack) {
898:       const ex = this.state.inventory.find(i => i.id === item.id);
899:       if (ex) ex.qty = (ex.qty || 1) + qty;
900:       else this.state.inventory.push({ ...item, qty });
901:     } else {
902:       for (let i = 0; i < qty; i++) this.state.inventory.push({ ...item, qty: 1 });
903:     }
904:     if (item.kind === 'loot') {
905:       this.state.lootCounts[item.id] = (this.state.lootCounts[item.id] || 0) + qty;
906:       this.checkQuests();
