912:   removeItem(id, qty = 1) {
913:     const inv = this.state.inventory;
914:     for (let i = inv.length - 1; i >= 0 && qty > 0; i--) {
915:       if (inv[i].id !== id) continue;
916:       const take = Math.min(qty, inv[i].qty || 1);
917:       inv[i].qty = (inv[i].qty || 1) - take;
918:       qty -= take;
919:       if (inv[i].qty <= 0) inv.splice(i, 1);
920:     }
921:   }
