1099:         ['Training: Look Around', 'Drag across the world to rotate your camera.'],
1100:         ['Training: A Gift', 'Your copper starter weapon and armor are being equipped.'],
1101:         ['Training: Strike', 'Press J, click, or tap Strike to attack.'],
1102:         ['Training: First Blood', `Slay moss slimes near Wayfarer's Rest (${Math.min(2, s.tutorial.kills)}/2).`],
1103:         ['Training: The Elder', 'Speak with Elder Maren by the fountain.'],
1104:       ];
1105:       const st = steps[s.tutorial.step] || steps[0];
1106:       return { title: st[0], objective: st[1] };
1107:     }
1108:     if (s.sigils.length < 4) {
1109:       const next = ZONE_ORDER.find(z => !s.sigils.includes(z));
