270:   Game.prototype.runEffects = function (effects) {
271:     let terminated = false;
272:     for (const eff of (Array.isArray(effects) ? effects : [effects])) {
273:       const [key, ...rest] = eff.split(':');
274:       const val = rest.join(':');
275:       switch (key) {
276:         case 'unity': this.state.flags.unity++; break;
277:         case 'insight': this.state.flags.insight++; break;
278:         case 'greed': this.state.flags.greed++; break;
279:         case 'gold': this.gainGold(Number(val), true); this.audio.sfx('coin'); break;
280:         case 'xp': this.gainXp(Number(val)); break;
281:         case 'tokens': this.state.tokens += Number(val); this.toast(`+${val} Gacha Token`, 'gold'); break;
282:         case 'heal': this.healPct(0.3); break;
283:         case 'completeTutorial': this.completeTutorial(); break;
284:         case 'sigil': {
285:           if (!this.state.sigils.includes(val)) {
286:             this.state.sigils.push(val);
287:             this.state.stage = this.state.sigils.length >= 4 ? 5 : 1;
288:             const z = ZONES[val];
289:             this.toast(`${z.name} Sigil recovered (${this.state.sigils.length}/4)`, 'gold');
290:             this.log(`Sigil of ${z.name} recovered.`, 'gold');
291:             this.audio.sfx('legendary');
292:             this.ring(this.playerMesh.position.x, this.playerMesh.position.y, this.playerMesh.position.z, '#ffd479', 4, 1.2);
293:             if (this.state.sigils.length >= 4) {
294:               this.toast('All four sigils resonate — seek the Sundered Throne.', 'gold');
295:               this.log('The four sigils sing. The Sundered Throne awaits.', 'gold');
296:             }
297:           }
298:           this.updateQuestUI(); this.updateHUD(true); this.save();
299:           break;
300:         }
301:         case 'storyReward': {
302:           const flag = 'rewarded_' + val;
303:           if (!this.state.flags[flag]) {
304:             this.state.flags[flag] = true;
305:             this.state.tokens += 1;
306:             this.gainGold(45, true);
307:             this.gainXp(90);
308:             this.toast('Storyteller reward — 1 Gacha Token', 'gold');
309:             this.audio.sfx('level');
310:             this.save();
311:           }
312:           break;
313:         }
314:         case 'openGacha':
315:           this.closeModal();
316:           this._endChain = true;
317:           setTimeout(() => this.openGacha(), 180);
318:           terminated = true;
319:           break;
320:         case 'ending':
321:           this.closeModal();
322:           terminated = true;
323:           this.triggerEnding(val);
324:           break;
325:       }
326:     }
327:     return terminated;
328:   };
