/* map */
.map-wrap { display: grid; grid-template-columns: 1fr 270px; gap: 18px; align-items: start; }
#worldmap { width: 100%; aspect-ratio: 1 / 1; border: 1px solid rgba(230, 193, 122, 0.2); background: #0a0f14; border-radius: 2px; cursor: crosshair; display: block; }
.map-side { display: flex; flex-direction: column; gap: 12px; }
.waypoint-list { display: flex; flex-direction: column; gap: 5px; max-height: 300px; overflow-y: auto; }
.wp-row { display: flex; align-items: center; justify-content: space-between; gap: 6px; padding: 8px 10px; border: 1px solid rgba(255, 255, 255, 0.08); background: rgba(255, 255, 255, 0.025); font-size: 9px; color: #ddd8ca; border-radius: 2px; transition: all 0.15s; text-align: left; }
.wp-row:hover { border-color: var(--gold-dim); background: rgba(230, 193, 122, 0.06); }
.wp-row.locked { opacity: 0.4; }
.wp-row span { font-size: 7px; color: var(--muted); letter-spacing: 0.08em; }
.map-legend { display: flex; flex-direction: column; gap: 5px; font-size: 8px; color: var(--muted); }
.map-legend div { display: flex; align-items: center; gap: 6px; }
.map-dot { width: 7px; height: 7px; border-radius: 50%; display: inline-block; }

/* journal */
.journal-grid { display: grid; grid-template-columns: 1.2fr 0.8fr; gap: 20px; }
.quest-card { padding: 13px 15px; border: 1px solid rgba(230, 193, 122, 0.14); background: rgba(255, 255, 255, 0.02); margin-bottom: 8px; }
.quest-card.done { opacity: 0.55; border-color: rgba(255, 255, 255, 0.08); }
.quest-card h4 { font-family: var(--serif); font-size: 12px; color: var(--gold); margin: 0 0 3px; font-weight: 500; letter-spacing: 0.04em; }
.quest-card p { font-size: 9px; color: #b0b8be; line-height: 1.55; margin: 0 0 6px; }
.quest-progress { height: 3px; background: rgba(0, 0, 0, 0.5); margin-top: 6px; }
.quest-progress i { display: block; height: 100%; background: var(--gold); }
.quest-meta { display: flex; gap: 10px; font-size: 7.5px; color: var(--muted); margin-top: 5px; flex-wrap: wrap; }
.quest-meta b { color: var(--gold); }
.ending-mini { display: flex; align-items: center; gap: 8px; padding: 8px 10px; border: 1px solid rgba(255, 255, 255, 0.08); margin-bottom: 5px; font-size: 9px; color: var(--muted); }
.ending-mini.unlocked { border-color: color-mix(in srgb, var(--ec) 40%, transparent); color: #e8e2d4; }
.ending-mini .em-icon { font-size: 14px; color: var(--ec); }
.ending-mini em { display: block; font-size: 7px; color: var(--muted); letter-spacing: 0.08em; margin-top: 1px; }
.ending-mini.locked .em-icon { filter: grayscale(1); opacity: 0.4; }
.lore-list { display: flex; flex-direction: column; gap: 5px; }
.lore-item { font-size: 9px; color: #aab2b8; line-height: 1.5; padding: 7px 9px; border-left: 1px solid var(--gold-dim); background: rgba(255, 255, 255, 0.02); }

/* dialogue */
.modal.dialogue { width: min(780px, 94vw); }
.dlg-body { display: flex; gap: 18px; padding: 22px 26px 8px; }
.dlg-portrait { flex: 0 0 104px; height: 124px; position: relative; border: 1px solid var(--gold-dim); background: radial-gradient(circle at 50% 40%, var(--pc, #8a7aa0), transparent 72%), rgba(0, 0, 0, 0.35); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; overflow: hidden; }
.dlg-portrait::after { content: ''; position: absolute; inset: 4px; border: 1px solid rgba(255, 255, 255, 0.08); }
.dlg-portrait .dp-face { font-family: var(--serif); font-size: 40px; color: rgba(255, 255, 255, 0.9); text-shadow: 0 2px 20px rgba(0, 0, 0, 0.6); }
.dlg-portrait .dp-role { font-size: 6px; letter-spacing: 0.12em; text-transform: uppercase; color: rgba(255, 255, 255, 0.6); padding: 0 4px; text-align: center; }
.dlg-main { flex: 1; min-width: 0; }
.dlg-name { font-family: var(--serif); font-size: 15px; color: var(--gold); letter-spacing: 0.08em; margin-bottom: 7px; display: flex; align-items: baseline; gap: 8px; }
.dlg-name em { font-size: 7px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--muted); }
.dlg-text { font-size: 11.5px; line-height: 1.85; color: #d6d4ca; font-weight: 300; min-height: 68px; }
.dlg-text .hl { color: var(--gold); }
.dlg-choices { display: flex; flex-direction: column; gap: 5px; padding: 4px 26px 18px; }
.dlg-choice { display: flex; gap: 10px; align-items: flex-start; text-align: left; padding: 9px 13px; border: 1px solid rgba(255, 255, 255, 0.08); background: rgba(255, 255, 255, 0.02); font-size: 10px; color: #cfd2ce; line-height: 1.5; border-radius: 2px; transition: all 0.16s; }
.dlg-choice:hover { border-color: var(--gold-dim); background: rgba(230, 193, 122, 0.06); color: #f0e8d8; transform: translateX(3px); }
.dlg-choice .num { color: var(--gold); font-size: 8px; min-width: 12px; opacity: 0.7; padding-top: 1px; }
.dlg-choice.secret { border-color: rgba(197, 140, 255, 0.3); }
.dlg-choice.secret .num { color: #c58cff; }
.dlg-choice.danger .num { color: #e07a6a; }
.dlg-continue { display: flex; justify-content: flex-end; padding: 0 26px 18px; }
.dlg-hint { padding: 0 26px 12px; font-size: 8px; color: var(--muted); letter-spacing: 0.08em; }

/* ending */
.modal.ending-modal { width: min(720px, 94vw); background: radial-gradient(circle at 50% 10%, color-mix(in srgb, var(--endcol) 18%, transparent), transparent 60%), linear-gradient(160deg, rgba(17, 24, 33, 0.99), rgba(6, 9, 14, 0.99)); border-color: color-mix(in srgb, var(--endcol) 50%, transparent); }
.ending-body { text-align: center; padding: 30px 46px 32px; }
.ending-icon { font-size: 48px; color: var(--endcol); text-shadow: 0 0 50px var(--endcol); margin-bottom: 12px; }
.ending-kicker { font-size: 8px; letter-spacing: 0.4em; text-transform: uppercase; color: var(--muted); margin-bottom: 8px; }
.ending-title { font-family: var(--serif); font-size: clamp(26px, 4vw, 38px); letter-spacing: 0.06em; color: var(--endcol); margin: 0 0 18px; line-height: 1.15; }
.ending-text { font-size: 11.5px; line-height: 2; color: #cfccc0; font-weight: 300; text-align: left; margin: 0 0 22px; }
.ending-stats { display: flex; justify-content: center; gap: 26px; padding: 14px 0; border-top: 1px solid rgba(255, 255, 255, 0.08); border-bottom: 1px solid rgba(255, 255, 255, 0.08); margin-bottom: 20px; flex-wrap: wrap; }
.ending-stats div { display: flex; flex-direction: column; gap: 2px; }
.ending-stats b { font-family: var(--serif); font-size: 17px; color: var(--gold); }
.ending-stats span { font-size: 7px; letter-spacing: 0.17em; text-transform: uppercase; color: var(--muted); }
.ending-actions { display: flex; justify-content: center; gap: 8px; flex-wrap: wrap; }

/* help */
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.help-card { padding: 12px 14px; border: 1px solid rgba(230, 193, 122, 0.14); background: rgba(255, 255, 255, 0.02); }
.help-card h4 { margin: 0 0 6px; font-family: var(--serif); font-size: 12px; color: var(--gold); font-weight: 500; letter-spacing: 0.06em; }
.help-card p, .help-card li { font-size: 9px; line-height: 1.7; color: #b0b8be; margin: 0; }

